YH_EXAM_BANKS["MGT102-CH1"] = {"id":"MGT102-CH1","short":"الفصل الأول","version":1,"los":[{"lo":"LO1-1","en":"Describe what management is, why management is important, what managers do, and how managers use organizational resources efficiently and effectively to achieve organizational goals.","ar":"وش هي الإدارة والكفاءة والفعالية"},{"lo":"LO1-2","en":"Distinguish among planning, organizing, leading, and controlling (the four principal managerial functions), and explain how managers' ability to handle each one affects organizational performance.","ar":"وظائف الإدارة الأربع وأدوار Mintzberg"},{"lo":"LO1-3","en":"Differentiate among three levels of management, and understand the tasks and responsibilities of managers at different levels in the organizational hierarchy.","ar":"مستويات الإدارة الثلاثة ومهام كل مستوى"},{"lo":"LO1-4","en":"Distinguish among three kinds of managerial skill, and explain why managers are divided into different departments to perform their tasks more efficiently and effectively.","ar":"المهارات الثلاث وليش المديرين في أقسام"},{"lo":"LO1-5","en":"Discuss some major changes in management practices today that have occurred as a result of globalization and the use of advanced technologies.","ar":"التغيّرات الحديثة في شغل المديرين"},{"lo":"LO1-6","en":"Discuss the principal challenges managers face in today's increasingly competitive global environment.","ar":"تحديات الإدارة في البيئة العالمية"}],"sections":{"MGT102-CH1-S1":{"ar":"وش هي الإدارة؟","en":"What Is Management?"},"MGT102-CH1-S2":{"ar":"وظائف الإدارة الأربع","en":"The Four Functions of Management"},"MGT102-CH1-S3":{"ar":"مستويات المديرين ومهاراتهم","en":"Levels and Skills of Managers"},"MGT102-CH1-S4":{"ar":"التغيّرات الحديثة والتحديات العالمية","en":"Recent Changes and Global Challenges"}},"misconceptions":[{"id":"c1.eff-vs-effect","ar":"تخلط بين الكفاءة والفعالية","explain":"تبدّل efficiency (استخدام الموارد بإنتاجية: أقل مدخلات أو وقت لنفس المخرجات) مع effectiveness (اختيار أهداف مناسبة appropriate goals وتحقيقها). يعني تشوف «أقل زيت وأسرع طبخ» وتقول effectiveness، أو «قرروا يقدّمون فطور والزبائن حبّوه» وتقول efficiency.","fix":"ارجع لمفهوم «الكفاءة والفعالية والأداء» في درس S1 واقرأ جدول المقارنة (كيف؟ ضد وش؟) وصندوق الفخ، وبعدها أعد بطاقات S1 (زر 🃏 تدرّب) على الكلمتين.","sec":"MGT102-CH1-S1","coach":"قل له أمثلة الكتاب بسرعة (Wendy's أقل زيت، UPS باب الشاحنة مفتوح، McDonald's فطور طول اليوم) وخلّه يرد بكلمة وحدة: «كيف» يعني efficiency و«وش» يعني effectiveness. كمّل لين يجاوب خمسة ورا بعض بدون تردد."},{"id":"c1.fig11-cells","ar":"تقلب خانات Figure 1.1","explain":"تعكس الخانتين المختلطتين: High efficiency/low effectiveness نتيجتها منتج جودته عالية بس الزبون ما يبيه، و Low efficiency/high effectiveness نتيجتها منتج الزبون يبيه بس غالي عليه. أو تطلّع نتيجة High/High في خانة ثانية.","fix":"افتح Figure 1.1 في مفهوم «الكفاءة والفعالية والأداء» (S1) واقرأ العنوان المكتوب داخل كل خانة وسطر Result تحته، واعتمد على الكلام اللي داخل الخانة مو على مكانها، وبعدين حلّ سؤال ٤ من «اختبر نفسك» مرة ثانية.","sec":"MGT102-CH1-S1","coach":"اسأله: «هدف صح بس بذّر الموارد، وش يطلع؟» ولازم يقول «منتج الزبون يبيه بس غالي». وبعدين اسأله «هدف غلط بس شغل نظيف؟» ولازم يقول «جودة عالية ما أحد يبيه»، وبدّل الترتيب كل مرة لين يثبت."},{"id":"c1.one-e-only","ar":"تاخذ نص التعريف: كفاءة بس أو فعالية بس","explain":"organizational performance و management و competitive advantage كلها تحتاج الكلمتين مع بعض (efficiently and effectively)، وأنت تختار الاختيار اللي فيه وحدة بس. مثلاً تختار تعريف efficiency لحاله وتحسبه تعريف الأداء.","fix":"ارجع لسؤال ٥ في «اختبر نفسك» بدرس S1 وصندوق الفخ تحت «الكفاءة والفعالية والأداء»، واكتب التعاريف الثلاثة وحط خط تحت efficiently and effectively في كل واحد.","sec":"MGT102-CH1-S1","coach":"اقرأ له بداية تعريف (organizational performance، management، competitive advantage) وخلّه يكمّل نهايته بصوت عالي. أي مرة يقول كلمة وحدة بس وقّفه وخلّه يعيدها بالكلمتين."},{"id":"c1.org-resources","ar":"تفهم المنظمة وموارد المدير فهم ناقص","explain":"تحسب organization مبنى أو شركة مسجّلة، وهي عند الكتاب collections of people ينسّقون أفعالهم (coordinate their actions) عشان أهداف. وبرضو تستبعد loyal customers أو patents أو know-how من الموارد، أو تحسب المدير يشرف على الناس بس مو human and other resources.","fix":"أعد مفهومي «المنظمات والمديرين» و«الإدارة والموارد التنظيمية» في S1، واحفظ قائمة الموارد اللي في الشرح، وراجع سؤال ١ في «اختبر نفسك».","sec":"MGT102-CH1-S1","coach":"اسأله «المنظمة وش هي؟» ولازم يقول «ناس ينسّقون شغلهم عشان هدف» مو مبنى. بعدها خلّه يعدّ موارد الكتاب من ذاكرته، وتأكد إنه ما ينسى patents و loyal customers and employees."},{"id":"c1.why-study","ar":"تلخبط أسباب دراسة الإدارة وأرقامها","explain":"تفهم social learning إنه مذاكرة مع مجموعة، وهو عند الكتاب تتعلّم من تجارب غيرك عشان ما تكرر أغلاطهم. أو تلخبط الأرقام: median wage قدره $97,970 ونمو الوظايف 4%–7% لين 2031.","fix":"ارجع لمفهوم «ليش ندرس الإدارة؟» في S1: جدول الأسباب الأربعة وصندوق الفخ، وراجع بطاقة Social learning في بطاقات S1.","sec":"MGT102-CH1-S1","coach":"اسأله: «كم سبب لدراسة الإدارة؟ عدّها»، وبعدين «social learning يعني وش؟». وآخر شي اسأله عن الرقمين ($97,970 و 4–7% لين 2031) وخلّه يقول إنه median مو average."},{"id":"c1.four-functions","ar":"تغلط في عدد وظائف الإدارة أو ترتيبها","explain":"تدخّل وظيفة مو منها زي staffing أو negotiating أو marketing أو motivating، أو تقول خمس وظايف لأن Fayol أصلاً حدّد خمس مهام بس الكتاب يعتمد الأربع. أو تلخبط الترتيب planning ← organizing ← leading ← controlling اللي في أسهم Figure 1.2 (والرقابة ترجّع للتخطيط).","fix":"أعد مفهوم «وظائف الإدارة الأربع» في S2 وتتبّع أسهم Figure 1.2 بإصبعك من Planning لين ترجع لها، واقرأ صندوق الفخ.","sec":"MGT102-CH1-S2","coach":"خلّه يقول الأربع بالترتيب ثلاث مرات ورا بعض، وبعدين اسأله «وش بعد organizing؟ ووش يجي بعد controlling؟». ولو قلت له negotiating أو staffing لازم يقول فوراً «مو وظيفة»."},{"id":"c1.theorists","ar":"تخلط بين Fayol و Mintzberg","explain":"تعطي Mintzberg الوظائف الأربع أو تعطي Fayol الأدوار العشرة، أو تخلط role (عند Mintzberg) مع function (عند Fayol). وممكن تحسب Mintzberg قال الإدارة مرتّبة وهادية، وهو قال إنها chaotic وقراراتها سريعة (snap decisions) بالحدس.","fix":"اقرأ صندوق الفخ في «وظائف الإدارة الأربع» (Fayol) و«الشرح» في «أدوار المدير عند منتزبرغ» في S2، واكتب جدول صغير: الاسم، وش قدّم، ومن وين (مدير فرنسي / أستاذ في McGill).","sec":"MGT102-CH1-S2","coach":"قل الاسم وخلّه يرد بسرعة: Fayol ← «٤ وظائف»، Mintzberg ← «١٠ أدوار في ٣ فئات، والإدارة فوضوية». وبعدين قل «role» أو «function» وخلّه يقول تبع مين."},{"id":"c1.plan-vs-control","ar":"تخلط بين التخطيط والرقابة","explain":"الثنتين فيهم كلمة goals فتلخبط: planning يختار ويحدد الأهداف (choose, select, decide)، و controlling يقيّم وش تحقق ويصحّح (evaluate, measure, corrective action). تشوف «يقارن النتايج بالمعايير ويصحّح» وتقول planning.","fix":"ارجع لسطر «Planning مقابل Controlling» في صندوق الفخ بمفهوم «التخطيط والتنظيم»، وسطر corrective action في فخ «القيادة والرقابة» (S2)، وأعد سؤال ١ و٤ من «اختبر نفسك».","sec":"MGT102-CH1-S2","coach":"قل له أفعال بالإنجليزي (choose, evaluate, select, measure, decide, monitor, corrective action) وخلّه يرد «تخطيط» أو «رقابة» على كل وحدة. بعدها اعطه موقف قصير من عندك ويحدد هو الوظيفة."},{"id":"c1.plan-vs-organize","ar":"تحط توزيع الموارد تحت التنظيم بدل التخطيط","explain":"planning له ثلاث خطوات بالترتيب: يقرر الأهداف، بعدين الاستراتيجيات، بعدين how to allocate resources، وأنت تحسب الخطوة الثالثة organizing. و organizing عند الكتاب هيكلة علاقات الشغل (task and authority relationships) مو توزيع ميزانية.","fix":"أعد «الشرح — التخطيط» في مفهوم «التخطيط والتنظيم» (S2) واكتب الخطوات الثلاث من ذاكرتك، واقرأ سطر allocate resources في صندوق الفخ.","sec":"MGT102-CH1-S2","coach":"اسأله: «خطوات التخطيط كم؟ عدّها بالترتيب» ولازم يقول أهداف ← استراتيجيات ← توزيع موارد. وبعدين قل «allocate resources» وخلّه يرد «تخطيط، الخطوة الثالثة»."},{"id":"c1.org-vs-lead","ar":"تخلط بين التنظيم والقيادة","explain":"organizing = هيكل رسمي وعلاقات مهام وسلطة (task and authority relationships)، و leading = يصيغ vision ويحفّز وينشّط الناس (motivate, energize). وممكن تحط vision تحت planning، وهي في الكتاب جزء من تعريف leading.","fix":"اقرأ «الشرح — التنظيم» و«الشرح — القيادة» في S2 وصندوق الفخ في «القيادة والرقابة»، وقارن نص دائرتي Organizing و Leading في Figure 1.2.","sec":"MGT102-CH1-S2","coach":"قل كلمات (structure, authority, reporting, departments, vision, motivate, energize, inspire) وخلّه يرد «تنظيم» أو «قيادة». وأي مرة يقول vision = تخطيط صحّحه على طول."},{"id":"c1.function-outcomes","ar":"تبدّل نواتج الوظائف الأربع","explain":"ناتج organizing هو organizational structure، وناتج leading قوة عاملة motivated and committed، وناتج controlling القدرة على قياس الأداء بدقة (measure performance accurately). وأنت تبدّلهم، أو تحسب controlling منفصلة عن الباقي وهي تقيّم الوظايف الثلاث الثانية كمان.","fix":"ارجع لـ EXAM BOX وصندوق الفخ في مفهومي «التخطيط والتنظيم» و«القيادة والرقابة» (S2)، وسوّ جدول صغير: الوظيفة ← ناتجها.","sec":"MGT102-CH1-S2","coach":"قل الناتج وخلّه يقول الوظيفة: «هيكل تنظيمي؟» ← organizing، «موظفين متحمسين وملتزمين؟» ← leading، «قياس الأداء بدقة؟» ← controlling. بعدين اعكس: قل الوظيفة وهو يقول ناتجها."},{"id":"c1.role-category","ar":"تحط أدوار Mintzberg في فئة غلط","explain":"ما تعرف توزيع الأدوار العشرة على الفئات الثلاث (4 decisional، 3 interpersonal، 3 informational). مثلاً تحط negotiator أو resource allocator في interpersonal لأنهم يتعاملون مع ناس، أو figurehead في informational.","fix":"أعد جدول Table 1.1 في مفهوم «أدوار المدير عند منتزبرغ» (S2): غطّ عمود الأدوار وحاول تكتبها تحت كل فئة، وبعدين اقرأ صندوق الفخ.","sec":"MGT102-CH1-S2","coach":"قل اسم الدور وخلّه يرد بالفئة: decisional ولا interpersonal ولا informational. وبعدين اسأله «كم دور؟ كم فئة؟ كم في كل فئة؟» لين يقول 10 و3 و4-3-3 بدون تفكير."},{"id":"c1.role-activity","ar":"تطابق نشاط المدير مع دور غلط","explain":"تلخبط الأدوار المتقاربة في Table 1.1: figurehead رمزي (يفتتح مبنى، يعلن المبادئ) و leader فعلي (أوامر مباشرة، قدوة)، و monitor يجمع ويقيّم، و disseminator يبلّغ الموظفين داخل الشركة، و spokesperson يتكلم للخارج. وبرضو تحط مشكلة مفاجئة تحت entrepreneur وهي disturbance handler.","fix":"اقرأ عمود «وش يسوي» في جدول الأدوار بمفهوم «أدوار المدير عند منتزبرغ» (S2)، وركّز على سطر «ثلاثة يتكلمون، بس لمين؟» في صندوق الفخ.","sec":"MGT102-CH1-S2","coach":"اعطه مواقف قصيرة (يقص شريط افتتاح، يطلق حملة إعلانية وطنية، يبلّغ الموظفين بتغيير، يفاوض نقابة، يتصرف في تسرّب نفط) وخلّه يسمّي الدور. لو قال figurehead مكان leader اسأله: «رمزي ولا أوامر فعلية؟»."},{"id":"c1.level-duties","ar":"تبدّل مهام المستويات الإدارية الثلاثة","explain":"first-line يشرف يومياً على nonmanagerial employees، و middle يشرف على first-line ويدوّر أحسن طريقة لاستخدام الموارد ويقترح تعديل الأهداف، و top يحدد الأهداف وعنده cross-departmental responsibility. وأنت تبدّلهم، أو تعدّ الـ CEO مستوى رابع والمستويات ثلاثة بس.","fix":"أعد مفهوم «مستويات الإدارة الثلاثة» في S3 مع Figure 1.3، واقرأ صندوق الفخ خصوصاً سطر «يقترح ≠ يحدّد».","sec":"MGT102-CH1-S3","coach":"قل له مهمة وخلّه يرد بالمستوى: «إشراف يومي» ← first-line، «يقترح تغيير الأهداف» ← middle، «يحدد الأهداف ومسؤول عن كل الأقسام» ← top. واسأله «كم مستوى؟» ولازم يقول ثلاثة."},{"id":"c1.ceo-coo-tmt","ar":"تخلط CEO و COO وفريق الإدارة العليا","explain":"CEO أعلى وأهم مدير وكل المديرين الكبار يرفعون له، و COO مدير أعلى being groomed يعني يتجهّز يصير CEO، و top management team = CEO + COO + نواب الرئيس (vice presidents). وأنت تبدّلهم أو تدخّل المديرين الأوسطين في الفريق.","fix":"اقرأ «الشرح» وصندوق الفخ في مفهوم «مستويات الإدارة الثلاثة» (S3) عند CEO و COO، وراجع بطاقاتهم في بطاقات S3.","sec":"MGT102-CH1-S3","coach":"اسأله: «مين يتجهّز يصير CEO؟» ← COO، و«مين في top management team؟» ← CEO و COO ونواب الرئيس. وبعدين اسأله «المدير الأوسط منهم؟» ولازم يقول لا."},{"id":"c1.fig14-time","ar":"تقلب توزيع الوقت في Figure 1.4","explain":"كل ما صعد المدير زاد وقته على planning و organizing، وكل ما نزل زاد وقته على leading و controlling، وأنت تعكسها. أو تفهم من الشكل إن first-line ما يخطط أبد، والصح كلهم يسوون الأربع والفرق نسبي بس.","fix":"افتح Figure 1.4 في مفهوم «توزيع الوقت على الوظائف الأربع» (S3) وقارن عرض كل قطعة في صف Top managers مع صف First-line managers، واقرأ صندوق الفخ.","sec":"MGT102-CH1-S3","coach":"اسأله: «المدير الأعلى وين يصرف أكثر وقته؟» ← planning و organizing، و«مدير الخط الأول؟» ← leading و controlling. وبعدين قل «first-line managers do not plan» وخلّه يقول غلط وليش."},{"id":"c1.skills-swap","ar":"تخلط بين المهارات الإدارية الثلاث","explain":"conceptual = تحليل وتشخيص الموقف والتفريق بين cause and effect، و human = فهم وتغيير وقيادة سلوك الأفراد والمجموعات، و technical = job-specific knowledge and techniques. وأنت تبدّلهم، أو تحسب decisional و interpersonal مهارات وهي فئات أدوار عند Mintzberg.","fix":"أعد مفهوم «أنواع المهارات الإدارية الثلاثة» في S3 وصندوق الفخ، وراجع بطاقات المهارات في بطاقات S3.","sec":"MGT102-CH1-S3","coach":"قل له كلمة مفتاح وخلّه يرد بالمهارة: cause and effect ← conceptual، behavior of others ← human، job-specific ← technical. وبعدين اعطه أمثلة (مدير مطعم يطبخ مكان طبّاخ غايب، مدير يهدّي خلاف بين موظفين، CEO يحلل سبب نزول المبيعات)."},{"id":"c1.top-conceptual","ar":"تربط المهارة بالمستوى الإداري غلط","explain":"top managers يحتاجون أقوى conceptual skills لأن شغلهم الأساسي planning و organizing، وأنت تختار technical. وبرضو ما تعرف إن غياب مهارة وحدة ممكن يودّي للفشل (صاحب مشروع عنده technical بس ناقصه conceptual و human)، وإن المهارات تنتعلم مو فطرية.","fix":"اقرأ «الشرح» وصندوق الفخ في مفهوم «أنواع المهارات الإدارية الثلاثة» (S3)، واربطها بـ Figure 1.4: وقت top على planning و organizing يعني يحتاجون conceptual.","sec":"MGT102-CH1-S3","coach":"اسأله: «Top managers require the best ___ skills؟» ولازم يقول conceptual ويشرح ليش بجملة. بعدين اعطه قصة مهندس ممتاز صار مدير وفشل، واسأله وش المهارة الناقصة (human)."},{"id":"c1.dept-core","ar":"تخلط القسم بالمستوى أو الكفاءة الجوهرية بالميزة","explain":"department مجموعة ناس بنفس المهارات (technical)، وكل قسم فيه الثلاث مستويات كلها زي ما يبيّن Figure 1.5، وأنت تحسب القسم مستوى أو تخلط Figure 1.3 مع 1.5. وبرضو تبدّل core competency (مهارات القسم اللي تخلّي الشركة تتفوّق، زي Dell في materials management) مع competitive advantage اللي هي النتيجة.","fix":"أعد مفهوم «الأقسام والكفاءة الجوهرية» في S3 مع Figure 1.5 وجدول Dell و Google، واقرأ صندوق الفخ.","sec":"MGT102-CH1-S3","coach":"اسأله: «قسم التسويق فيه كم مستوى إداري؟» ولازم يقول الثلاثة. وبعدين قل «Google شاطرة في R&D» واسأله: هذي core competency ولا competitive advantage، ووش النتيجة اللي تجيبها؟"},{"id":"c1.restruct-vs-outsource","ar":"تخلط بين إعادة الهيكلة والاستعانة بمصادر خارجية","explain":"restructuring = تصغير الشركة من داخل بإلغاء وظائف مديرين وموظفين (downsizing)، و outsourcing = تعاقد مع شركة ثانية (عادة برا البلد) تسوي نشاط كانت الشركة تسويه بنفسها. الثنتين يوفّرون تكاليف فتلخبط بينهم، أو تنسى إن restructuring لها سلبيات (معنويات أقل وخدمة أسوأ).","fix":"أعد مفهوم «إعادة الهيكلة والاستعانة بمصادر خارجية» في S4 وصندوق الفخ، وراجع بطاقتيهم في بطاقات S4.","sec":"MGT102-CH1-S4","coach":"اعطه موقفين: «شركة ألغت مستويين إداريين وسرّحت 500 موظف» و«بنك نقل خدمة العملاء لشركة في الفلبين»، وخلّه يسمّي كل واحد ويقول وش فرّق بينهم (من داخل ولا شركة ثانية)."},{"id":"c1.empower-teams","ar":"تفهم التمكين والفرق ذاتية الإدارة غلط","explain":"empowerment = توسيع معرفة الموظف ومهامه ومسؤوليات القرار عنده، مو زيادة راتب ولا ترقية. ومع self-managed work teams مدير الخط الأول ما ينلغي بل يصير coach or mentor، وممكن تلخبط remote workers (عدة مرات بالأسبوع، والإنتاجية زادت مو نقصت).","fix":"أعد مفهوم «التمكين · فرق الإدارة الذاتية · العمل عن بُعد» في S4 وصندوق الفخ، وراجع مثال Valve في الشرح.","sec":"MGT102-CH1-S4","coach":"اسأله: «مع الفرق الذاتية، وش يصير لمدير الخط الأول؟» ولازم يقول coach or mentor. وبعدين قل تعريف empowerment ناقص كلمة وخلّه يكمّله (knowledge, tasks, decision-making responsibilities)."},{"id":"c1.challenges-vs-blocks","ar":"تلخبط التحديات الخمس ولبنات الميزة الأربع","explain":"التحديات الخمس: competitive advantage، ethics، diversity، new technologies، global crisis management؛ واللبنات الأربع في Figure 1.6: efficiency، quality، innovation and flexibility، responsiveness to customers. وأنت تخلط القائمتين، أو تدخّل عليها restructuring أو outsourcing أو profit، أو تقرأ أسهم الشكل بالعكس.","fix":"أعد مفهوم «الميزة التنافسية» في S4 مع Figure 1.6 (الأسهم كلها تصب في المربع اللي بالنص) وصندوق الفخ، واكتب القائمتين من ذاكرتك جنب بعض.","sec":"MGT102-CH1-S4","coach":"اطلب منه يعدّ التحديات الخمس بالترتيب، بعدين اللبنات الأربع. وبعدين قل عناصر مخلوطة (quality، outsourcing، diversity، profit، responsiveness to customers) وخلّه يقول: تحدي، لبنة، ولا ولا وحدة."},{"id":"c1.innovation-speed","ar":"تخلط الابتكار والسرعة والمرونة","explain":"innovation = إنشاء سلع وخدمات جديدة أو محسّنة أو طرق أحسن لإنتاجها أو تقديمها، مو بس منتج جديد. و speed = كم بسرعة تطرح منتج جديد، و flexibility = كم بسهولة تغيّر طريقة شغلك عشان ترد على المنافسين، واللي عنده الثنتين agile competitor.","fix":"اقرأ صف «Innovation and flexibility» في جدول اللبنات بمفهوم «الميزة التنافسية» (S4)، ومثال Google 80/20 و X lab، وسطر speed ≠ flexibility في صندوق الفخ.","sec":"MGT102-CH1-S4","coach":"قل له: «شركة تنزّل موديل جديد كل ثلاث شهور» و«شركة غيّرت طريقة البيع بأسبوع لما المنافس نزّل عرض»، وخلّه يقول speed ولا flexibility. وبعدين اسأله: «Google للحين تستخدم 80/20؟» ← لا، تعتمد على X lab."},{"id":"c1.turnaround-mix","ar":"تخلط إدارة التحوّل بإعادة الهيكلة وإدارة الأزمات","explain":"turnaround management = رؤية جديدة لشركة متعثّرة مبنية على نهج جديد في planning و organizing عشان تنجو وتزدهر (Steve Jobs في Apple، Brian Niccol في Chipotle). وأنت تخلطها مع restructuring (أداة تصغير) أو crisis management (التحدي الخامس عن الكوارث والأزمات).","fix":"اقرأ فقرة «ولما كل شي يفشل — Turnaround management» في مفهوم «الميزة التنافسية» (S4) وسطر الفخ اللي عنها.","sec":"MGT102-CH1-S4","coach":"اسأله: «شركة قربت تفلس وجابوا CEO جديد برؤية جديدة، وش اسم هذا؟» ولازم يقول turnaround management. وبعدين خلّه يقول الفرق بينها وبين restructuring بجملة وحدة."},{"id":"c1.ethics-csr-diversity","ar":"تلخبط الأخلاق والمسؤولية الاجتماعية والتنوّع","explain":"ethics تخص سلوك المدير (رشاوى، sweatshops)، و social responsibility = التزامات الشركة تجاه الناس المتأثرين بشغلها (موظفين، زبائن، مدن). وإدارة diversity عند الكتاب ethical need و legal requirement مع بعض، وأنت تاخذ وحدة بس، أو تحسب كل ضغط أداء ضار والكتاب يقول الضغط المعقول صحي.","fix":"أعد مفهوم «الأخلاق والمسؤولية الاجتماعية والتنوّع» في S4 واقرأ صندوق الفخ، خصوصاً سطر أسماء الشركات (Airbus رشاوى، Nike و Walmart و Apple ضد sweatshops، Accenture تنوّع).","sec":"MGT102-CH1-S4","coach":"اسأله: «إدارة التنوّع مطلب أخلاقي ولا قانوني؟» ولازم يقول الاثنين. وبعدين اعطه مثالين (مدير يدفع رشوة، شركة تقرر وش التزامها تجاه أهل المدينة) وخلّه يقول ethics ولا social responsibility."},{"id":"c1.crisis-causes","ar":"تصنّف أسباب الأزمات العالمية غلط","explain":"الكتاب يقسم أسباب الأزمات لنوعين بس: natural (أعاصير، حرائق، زلازل، مجاعات، أمراض) و human (تلوث صناعي، إهمال السلامة، تدمير البيئة، توترات وإرهاب، الجائحة الأخيرة). وأنت تحط الجائحة أو global warming تحت natural، أو ما تعرف الخيارات الأربع في crisis management.","fix":"أعد مفهوم «التقنيات الجديدة وإدارة الأزمات العالمية» في S4 وصندوق الفخ، واكتب قائمتي الأسباب والخيارات الأربع (teams، chain of command، recruit and select، bargaining and negotiating).","sec":"MGT102-CH1-S4","coach":"قل أسباب مخلوطة (زلزال، الجائحة، إرهاب، مجاعة، احتباس حراري، تلوث مصنع) وخلّه يرد natural ولا human. وبعدين اطلب منه يعدّ خيارات crisis management الأربع."}],"cases":[{"id":"C1-A","title":"Wadi Al-Aqiq Dates, Madinah","text":"Wadi Al-Aqiq Dates in Madinah has long made large luxury gift boxes of dates. Its factory is one of the most productive in the region: waste is very low, and each box costs little to make. The boxes are of high quality. However, young buyers now want small snack packs, not gift boxes. Gift-box sales have fallen by 40 percent, and shops keep returning unsold boxes.\n\nThe board asked the CEO, Hind Al-Harbi, to act. Hind decided that snack packs should reach 30 percent of sales within two years. She chose to sell them through petrol stations and university cafes, and she decided how much of the budget each product line would receive. Next, she combined the marketing and sales departments into one department and changed who reports to whom. Each month, she compares the sales of each product line with its target and acts when a line falls behind.\n\nIn the factory, Salem, the plant manager, reports to the vice president of operations. He supervises the three shift supervisors, including Faisal, who directs the packing workers every day. Salem looks for the best way to use the plant's machines, materials, and workers to reach the company's goals."},{"id":"C1-B","title":"Al-Qafilah Parcels, Riyadh","text":"Al-Qafilah Parcels is a profitable, growing delivery company in Riyadh with 600 employees. Last year, late deliveries rose sharply, and the drivers said heavy traffic was the reason. The CEO, Reem Al-Otaibi, did not simply accept this answer. She studied every step of the delivery process and saw that the delays were only a result. The real reason was in the warehouse: trucks were loaded in the wrong order, so drivers lost time searching for parcels at each stop.\n\nTo lower operating costs, Reem signed a contract with a company in the Philippines to run the customer call centre, a job Al-Qafilah had always done itself. The 40 call-centre staff in Riyadh moved to new jobs in the warehouse, so nobody lost a job.\n\nIn March, an earthquake hit a city in another country where the company's only supplier of handheld scanners is based, and scanner shipments stopped. Within hours, Reem formed a small team to make fast decisions and keep all drivers informed. She named one manager to lead the team and made clear who would report to whom until the problem was solved."}],"questions":[{"n":101,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"term","topic":"efficiency-definition","stem":"A measure of how well or how productively resources are used to achieve a goal is called:","options":["Effectiveness","Efficiency","Organizational performance","Organizational resources"],"answer":1,"why":"هذا تعريف efficiency بالحرف. الكلمة اللي تفضحه: how productively resources are used، يعني الكلام كله عن الموارد وطريقة استخدامها، وما فيه شي عن اختيار الهدف.","wrong":[{"i":0,"mis":"c1.eff-vs-effect","note":"أشهر فخ في الفصل: effectiveness عن مناسبة الأهداف وتحقيقها، مو عن إنتاجية الموارد."},{"i":2,"mis":"gen.neighbor","note":"organizational performance يقيس الاثنين مع بعض (efficiently and effectively)، والتعريف هنا فيه جزء الموارد بس."},{"i":3,"mis":"gen.keyword","note":"شاف كلمة resources في التعريف فاختارها، بس organizational resources هي الموارد نفسها (ناس، آلات، فلوس)، مو مقياس."}],"tests":["efficiency"]},{"n":102,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"term","topic":"effectiveness-definition","stem":"According to the textbook, effectiveness is a measure of:","options":["how well or how productively the organization's resources are used to achieve a goal","how appropriate an organization's goals are and the degree to which it achieves them","how appropriate an organization's goals are, whether or not it achieves them","how efficiently and effectively managers use resources to satisfy customers"],"answer":1,"why":"effectiveness فيها جزئين: الأهداف مناسبة (appropriateness) + قد إيش المنظمة حققتها (the degree to which). الخيار اللي فيه الجزئين مع بعض هو الصح.","wrong":[{"i":0,"mis":"c1.eff-vs-effect","note":"هذا تعريف efficiency، يتكلم عن إنتاجية الموارد مو عن الأهداف."},{"i":2,"mis":"gen.partial","note":"أخذ نص التعريف بس: عبارة whether or not it achieves them تشيل جزء التحقيق، والتعريف يبيه."},{"i":3,"mis":"gen.neighbor","note":"هذا قريب من تعريف organizational performance (efficiently and effectively مع بعض + satisfy customers)، يعني المقياس اللي يجمع الكفاءة والفعالية، مو الفعالية لحالها."}],"tests":["effectiveness"]},{"n":103,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"term","topic":"management-definition","stem":"Which of the following matches the textbook's definition of management?","options":["The planning, organizing, leading, and controlling of human and other resources to achieve organizational goals efficiently and effectively","The planning, organizing, staffing, and budgeting of human and other resources to achieve organizational goals quickly and efficiently","The planning, organizing, leading, and controlling of employees and their daily work to achieve organizational goals quickly and efficiently","The planning, organizing, staffing, and budgeting of employees and their daily work to achieve organizational goals efficiently and effectively"],"answer":0,"why":"تعريف management ثلاث قطع: الوظائف الأربع (planning, organizing, leading, controlling) + على human and other resources + efficiently and effectively مع بعض. الخيار الوحيد اللي القطع الثلاث فيه كلها صح هو الجواب.","wrong":[{"i":1,"mis":"c1.four-functions","note":"staffing و budgeting مو من الوظائف الأربع (الصح leading و controlling)، و quickly مكان effectively غلط كمان."},{"i":2,"mis":"c1.one-e-only","note":"حط quickly بدل effectively، والتعريف لازم فيه efficiently and effectively؛ وكمان حصر الموارد في الموظفين بدل human and other resources."},{"i":3,"mis":"c1.org-resources","note":"حصر الموارد في الموظفين وشغلهم، والتعريف يقول human and other resources (فلوس وآلات ومعلومات كمان)؛ و staffing و budgeting مو من الوظائف الأربع."}],"tests":["management","organizational resources","four functions of management"]},{"n":104,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"term","topic":"organizational-performance-definition","stem":"A measure of how efficiently and effectively a manager uses resources to satisfy customers and achieve organizational goals is called:","options":["Organizational performance","Effectiveness","Organizational resources","High-performing organization"],"answer":0,"why":"لما تشوف efficiently and effectively مع بعض + satisfy customers + achieve goals، هذا organizational performance: المقياس اللي يجمع الاثنين.","wrong":[{"i":1,"mis":"c1.one-e-only","note":"effectiveness نص الصورة بس (الأهداف)، والتعريف هنا يجمع الكفاءة معها."},{"i":2,"mis":"gen.keyword","note":"شاف كلمة resources في التعريف فاختارها، بس organizational resources هي الأشياء نفسها (ناس، آلات، فلوس)، مو مقياس."},{"i":3,"mis":"gen.keyword","note":"شاف efficiently and effectively فتذكّر high-performing organizations (الكتاب يقول كفؤة وفعّالة simultaneously)، بس هذي منظمة ناجحة، مو مقياس لاستخدام المدير للموارد."}],"tests":["organizational performance"]},{"n":105,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"concept","topic":"organizational-resources","stem":"According to the textbook's list of an organization's resources, which of the following is NOT a resource?","options":["The loyalty of its regular customers and employees","The patents it holds on its inventions","The skills, know-how, and experience of its people","The goals it wants to achieve in the future"],"answer":3,"why":"الموارد هي الأشياء اللي المدير يستخدمها عشان يوصل للأهداف، فالأهداف نفسها مو مورد، هي النتيجة المطلوبة. العملاء المخلصين وبراءات الاختراع ومهارات الناس كلها مذكورة بالاسم في قائمة الكتاب.","wrong":[{"i":0,"mis":"c1.org-resources","note":"يحسب الزبون شي برّا المنظمة، بس الكتاب يعدّ loyal customers and employees من الموارد."},{"i":1,"mis":"gen.detail","note":"patents شي معنوي فتحسبه مو مورد، بس الكتاب ذكرها بالاسم جنب financial capital."},{"i":2,"mis":"c1.org-resources","note":"مهارات الناس والـ know-how والخبرة أول شي في قائمة الموارد، لا تشطبها."}],"tests":["organizational resources"]},{"n":106,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"concept","topic":"performance-efficiency-effectiveness","stem":"Which statement about efficiency, effectiveness, and organizational performance is true according to the textbook?","options":["Performance improves as both efficiency and effectiveness improve together.","Performance is high as long as the organization is highly efficient, whatever its goals.","Efficiency is about choosing the right goals, while effectiveness is about saving resources.","Performance falls as efficiency rises, because using fewer resources lowers quality."],"answer":0,"why":"الكتاب يقول الأداء increases in direct proportion to increases in efficiency and effectiveness، يعني يزيد مع الاثنين مع بعض. والشركات عالية الأداء كفؤة وفعّالة simultaneously.","wrong":[{"i":1,"mis":"c1.one-e-only","note":"الكفاءة لحالها ما تكفي: لو الهدف غلط يطلع منتج عالي الجودة محد يبيه (Figure 1.1)."},{"i":2,"mis":"c1.eff-vs-effect","note":"قلب التعريفين: efficiency = استخدام الموارد، و effectiveness = اختيار الهدف الصح."},{"i":3,"mis":"gen.reversed","note":"عكس العلاقة: الأداء يزيد مع الكفاءة مو ينقص، وفي Figure 1.1 الكفاءة العالية مع هدف صح تعطي جودة وسعر مناسب."}],"tests":["organizational performance","efficiency","effectiveness","high-performing organizations"]},{"n":107,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"concept","topic":"organizations-definition","stem":"The textbook says a CEO, a fast-food restaurant manager, and a factory supervisor all work in organizations. Which statement about organizations is true, according to the textbook?","options":["An organization is people who work together and coordinate their actions toward goals.","An organization is the buildings, machines, and money that a business owns and uses.","An organization is its top executives, the people who set the goals for everyone else.","An organization is the planning, organizing, leading, and controlling of its resources."],"answer":0,"why":"تعريف organizations في الكتاب: collections of people who work together and coordinate their actions to achieve goals. يعني المنظمة ناس، والكلمة المفتاح coordinate: ينسّقون شغلهم مع بعض عشان يوصلون لأهداف.","wrong":[{"i":1,"mis":"c1.org-resources","note":"خلط المنظمة بمواردها: المباني والآلات والفلوس موارد المنظمة، والمنظمة نفسها هي الناس."},{"i":2,"mis":"c1.org-resources","note":"حصر المنظمة في الإدارة العليا، بس الكتاب يقول حتى مدير المطعم ومشرف المصنع يشتغلون فيها، والمنظمة هي كل الناس اللي ينسّقون شغلهم."},{"i":3,"mis":"gen.neighbor","note":"هذا تعريف management (الوظائف الأربع)، يعني شغل المدير داخل المنظمة، مو المنظمة نفسها."}],"tests":["organizations","manager"]},{"n":108,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"scenario","topic":"efficiency-vs-effectiveness","stem":"A logistics company in Jeddah changes its delivery routes. Its drivers now deliver the same number of parcels each day, but they use less fuel and finish in fewer hours. The company's goals and services did not change. Which statement best describes this change?","options":["It raised efficiency, because it needs fewer inputs and less time for the same output.","It raised effectiveness, because it chose a more appropriate goal for the company to pursue.","It raised effectiveness, because it now reaches its delivery targets in fewer hours.","It raised efficiency, because it chose goals that its customers value and desire."],"answer":0,"why":"نفس عدد الطرود (نفس الـ output) بوقود أقل وساعات أقل = قلّلوا الـ inputs والوقت، وهذا efficiency بالضبط زي مثال UPS. والأهداف ما تغيّرت، فما فيه شي يخص effectiveness.","wrong":[{"i":1,"mis":"c1.eff-vs-effect","note":"القصة تقول الأهداف ما تغيّرت؛ effectiveness عن اختيار هدف مناسب، وهنا بس غيّروا طريقة الشغل."},{"i":2,"mis":"gen.keyword","note":"عبارة reaches its delivery targets ذكّرته بتحقيق الأهداف، بس توفير الوقت لنفس الإنتاج هو efficiency حسب الكتاب."},{"i":3,"mis":"c1.eff-vs-effect","note":"الاسم صح بس السبب غلط: اختيار أهداف يبيها الزبون هو effectiveness، مو efficiency."}],"tests":["efficiency","effectiveness"]},{"n":109,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"scenario","topic":"efficiency-vs-effectiveness","stem":"A café manager in Madinah notices that many visitors want coffee late at night after Isha prayer. She decides to open until 2 a.m. instead of closing at 10 p.m. The new late-night hours quickly become the café's busiest time. What does this decision mainly show?","options":["Effectiveness: she chose an appropriate goal and the café achieved it.","Efficiency: she used fewer inputs and less time to serve each customer.","Social learning: she learned the lesson from other cafés' experience.","Low performance: the longer hours use more of the café's resources."],"answer":0,"why":"القرار هنا عن اختيار الهدف: شافت وش يبي الزبون، اختارت هدف مناسب (تفتح لين ٢ الفجر)، وحققته فعلاً. هذا effectiveness زي مثال فطور McDonald's، وما فيه أي كلام عن تقليل موارد أو وقت.","wrong":[{"i":1,"mis":"c1.eff-vs-effect","note":"ما في القصة شي عن تقليل الموارد أو الوقت؛ efficiency عن طريقة استخدام الموارد، وهنا الموضوع اختيار هدف."},{"i":2,"mis":"gen.neighbor","note":"social learning يعني تتعلّم من تجارب غيرك، وهي لاحظت زباينها بنفسها، ما أخذت الدرس من مقاهي ثانية."},{"i":3,"mis":"c1.one-e-only","note":"حكم على الأداء من كمية الموارد بس؛ الأداء يزيد مع effectiveness، والساعات الجديدة صارت أزحم وقت."}],"tests":["effectiveness"]},{"n":110,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"scenario","topic":"social-learning","stem":"Faisal will manage a new restaurant branch in Dammam. Before it opens, he reads case studies about managers whose branches failed, to find out what went wrong for them. Which idea from the textbook does this best illustrate?","options":["Social learning","Personal experience","Environmental contingencies","Effectiveness"],"answer":0,"why":"فيصل يتعلّم من تجارب غيره وأخطائهم قبل ما يبدأ = social learning. الكتاب يقول ميزتها إنك less likely to repeat the mistakes others have made.","wrong":[{"i":1,"mis":"c1.why-study","note":"فيصل ما جرّب بنفسه، قرأ تجارب غيره. الكتاب يقول نتعلّم يا من personal experience يا من تجارب الآخرين، والثانية هي social learning."},{"i":2,"mis":"c1.why-study","note":"environmental contingencies هي الظروف الطارئة في البيئة اللي المدير لازم يتعامل معها، مو طريقة تتعلّم فيها من أخطاء غيرك."},{"i":3,"mis":"gen.neighbor","note":"effectiveness مقياس لمناسبة الأهداف وقد إيش تحققت، مو طريقة للتعلّم."}],"tests":["social learning","personal experience","why study management","environmental contingencies"]},{"n":111,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"scenario","topic":"effective-managers","stem":"Reem and Sara each run a juice shop in Riyadh, and both sell the fresh drinks their customers ask for most. Reem wastes a lot of fruit and staff time, so her prices are high. Sara plans shifts and orders fruit carefully, so her prices stay low. Which of them fits the textbook's description of an effective manager, and why?","options":["Sara, because she chose goals customers value and uses resources efficiently","Reem, because choosing drinks that customers want is all an effective manager needs","Sara, because using fewer resources matters more than choosing the right goals","Reem, because her high prices show that her drinks are of high quality"],"answer":0,"why":"الكتاب يقول effective managers هم اللي يختارون الأهداف الصح (the right organizational goals) وعندهم المهارة يستخدمون الموارد بكفاءة (utilize resources efficiently). الثنتين اختاروا مشروبات يبيها الزبون، وهذا من أهم أهداف المنظمة: goods and services that customers value and desire، لكن سارة هي الوحيدة اللي ما تهدر الموارد، فهي اللي تجمع الشرطين.","wrong":[{"i":1,"mis":"c1.one-e-only","note":"أخذ نص الوصف بس (الهدف الصح)؛ الكتاب يقول المدير الفعّال لازم كمان يستخدم الموارد بكفاءة، وريم تهدر فاكهة ووقت."},{"i":2,"mis":"c1.eff-vs-effect","note":"الاسم صح بس السبب غلط: توفير الموارد هو efficiency، والكتاب ما يقول إنه أهم من اختيار الهدف؛ المدير الفعّال يحتاج الاثنين."},{"i":3,"mis":"c1.fig11-cells","note":"في Figure 1.1 الهدف الصح مع هدر الموارد يطلع منتج too expensive، مو جودة عالية؛ الجودة العالية تجي من الاستخدام الزين للموارد."}],"tests":["effective managers","key organizational goal","efficiency","effectiveness"]},{"n":112,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"figure","topic":"figure-1-1","stem":"Look at Figure 1.1. A manager uses the organization's resources very well, but the goals he picked are the wrong ones. What result does the figure show?","img":"img/mgt102/figure-1-1.png","options":["A high-quality product that customers do not want","A product that customers want, but that is too expensive for them to buy","A low-quality product that customers do not want","A product that customers want at a quality and price they can afford"],"answer":0,"why":"هدف غلط + استخدام زين للموارد = خانة High efficiency/low effectiveness، ونتيجتها في الشكل: منتج جودته عالية بس الزبون ما يبيه. الجودة جات من الكفاءة، وعدم الرغبة جا من الهدف الغلط.","wrong":[{"i":1,"mis":"c1.fig11-cells","note":"قلب الخانتين: المنتج الغالي اللي الزبون يبيه هو خانة الهدف الصح مع هدر الموارد."},{"i":2,"mis":"gen.partial","note":"شاف الهدف الغلط بس ونسى إنه استخدم الموارد زين؛ low-quality هي خانة low/low."},{"i":3,"mis":"c1.one-e-only","note":"حسب استخدام الموارد الزين يكفي، بس بدون هدف صح الزبون ما يبي المنتج أصلاً."}],"tests":["figure 1.1","efficiency","effectiveness"]},{"n":113,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"figure","topic":"figure-1-1","stem":"Look at Figure 1.1. What do the 'low efficiency/low effectiveness' box and the 'low efficiency/high effectiveness' box have in common?","img":"img/mgt102/figure-1-1.png","options":["The manager does a poor job of using resources","The manager chooses the right goals to pursue","Customers do not want the product that is made","Customers want the product but cannot afford it"],"answer":0,"why":"الخانتين تحت LOW في EFFICIENCY، يعني في الاثنين المدير يستخدم الموارد بشكل ضعيف: خانة low/low تقول makes poor use of resources، وخانة low/high تقول does a poor job of using resources. الفرق بينهم في الأهداف ورغبة الزبون، مو في الموارد.","wrong":[{"i":1,"mis":"c1.eff-vs-effect","note":"المشترك بين الخانتين هو low efficiency، والكفاءة عن الموارد مو الأهداف؛ وفي خانة low/low المدير أصلاً يختار wrong goals."},{"i":2,"mis":"gen.partial","note":"قرأ خانة low/low بس؛ في خانة low/high الزبون يبي المنتج (customers want)."},{"i":3,"mis":"c1.fig11-cells","note":"too expensive نتيجة خانة low/high بس؛ خانة low/low نتيجتها منتج جودته ضعيفة والزبون ما يبيه."}],"tests":["figure 1.1","efficiency","effectiveness"]},{"n":114,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"list","topic":"why-study-management","stem":"Which of the following gives the textbook's numbers on general managers in the United States (their pay, and the projected growth in their job openings until 2031)?","options":["$97,970 median wage; 4% to 7% projected growth in job openings","$97,970 average wage; 7% to 10% projected growth in job openings","$79,970 median wage; 7% to 10% projected growth in job openings","$79,970 average wage; 4% to 7% projected growth in job openings"],"answer":0,"why":"الكتاب يقول: general managers ياخذون median wage قدره $97,970، ومتوقّع نمو في job openings بين 4% و7% لين 2031. وانتبه: median يعني الوسيط، مو average.","wrong":[{"i":1,"mis":"gen.vocab","note":"قال average بدل median (الكتاب يقول median يعني الوسيط، مو المتوسط)، والنمو كمان غلط: 4% إلى 7% مو 7% إلى 10%."},{"i":2,"mis":"c1.why-study","note":"median صح بس الرقمين غلط: الأجر 97,970 مو 79,970، والنمو 4% إلى 7% مو 7% إلى 10%."},{"i":3,"mis":"c1.why-study","note":"النمو صح بس قلب أرقام الأجر (97,970 مو 79,970)، والكتاب يقول median مو average."}],"tests":["why study management","median wage","projected growth in job openings"]},{"n":115,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"list","topic":"management-functions-order","stem":"The textbook's definition of management names four activities. In what order does the definition list them?","options":["Planning, organizing, leading, controlling","Organizing, planning, controlling, leading","Planning, leading, organizing, controlling","Planning, organizing, controlling, leading"],"answer":0,"why":"التعريف يقول: The planning, organizing, leading, and controlling. احفظها بهالترتيب: تخطّط، بعدين تنظّم، بعدين تقود، وآخر شي تراقب.","wrong":[{"i":1,"mis":"c1.four-functions","note":"بدأ بـ organizing، بس التخطيط أول شي: ما تنظّم قبل ما تعرف الهدف."},{"i":2,"mis":"c1.four-functions","note":"قدّم leading على organizing، والتنظيم يجي قبل القيادة."},{"i":3,"mis":"c1.four-functions","note":"قدّم controlling على leading، والرقابة آخر وحدة في التعريف."}],"tests":["management","four functions of management"]},{"n":116,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"tf","topic":"why-study-management","stem":"According to the textbook, management principles help people make good decisions only in their jobs.","options":["True","False"],"answer":1,"why":"غلط. الكتاب يقول مبادئ الإدارة تساعدك حتى in nonwork contexts: تدريب فريق أطفال، تنظيم سباق خيري، ميزانيتك الشخصية، أو تبدأ بزنس. كلمة only هي الفخ.","wrong":[{"i":0,"mis":"gen.absolute","note":"كلمة only خدعته؛ الكتاب ذكر أمثلة برّا الشغل زي تدريب فريق أطفال وميزانيتك الشخصية."}],"tests":["why study management","nonwork contexts"]},{"n":117,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"vocab","topic":"vocab","stem":"In the sentence 'High-performing organizations are simultaneously efficient and effective,' the word simultaneously most nearly means:","options":["at the same time","one after the other","from time to time","for a short time"],"answer":0,"why":"simultaneously = في نفس الوقت. يعني الشركة الناجحة كفؤة وفعّالة مع بعض، مو وحدة وبعدين الثانية.","wrong":[{"i":1,"mis":"gen.vocab","note":"one after the other يعني وحدة بعد الثانية، وهذا عكس معنى الكلمة."},{"i":2,"mis":"gen.vocab","note":"from time to time يعني أحياناً، والكلمة ما تعني إن الشي يصير أحياناً."},{"i":3,"mis":"gen.vocab","note":"for a short time يعني لفترة قصيرة، ما له علاقة بـ simultaneously."}],"tests":["simultaneously","high-performing organizations"]},{"n":118,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"vocab","topic":"vocab","stem":"In the sentence 'Organizations need people who can respond to environmental contingencies,' the word contingencies most nearly means:","options":["events that may happen unexpectedly","rules that must always be followed","goals that are planned in advance","costs that stay the same every year"],"answer":0,"why":"contingency = طارئ، شي ممكن يصير فجأة وما تتوقعه. فالمنظمات تبي ناس يعرفون يتصرفون لما البيئة تتغيّر فجأة.","wrong":[{"i":1,"mis":"gen.vocab","note":"rules يعني قوانين، و contingency مو قانون، هي حدث طارئ."},{"i":2,"mis":"gen.vocab","note":"أهداف مخطط لها من قبل عكس المعنى؛ الطارئ شي ما خططت له."},{"i":3,"mis":"gen.vocab","note":"costs يعني تكاليف ثابتة، ما لها علاقة بمعنى الطوارئ."}],"tests":["contingency","environmental contingencies"]},{"n":119,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"vocab","topic":"vocab","stem":"What does the word appropriate mean? (as in: managers choose appropriate goals)","options":["مناسب","مُنتِج","متوقَّع","معقّد"],"answer":0,"why":"appropriate = مناسب، يعني الصح للموقف. وهي الكلمة المفتاح في تعريف effectiveness: the appropriateness of the goals.","wrong":[{"i":1,"mis":"gen.vocab","note":"مُنتِج = productive، وقريبة من productively (بإنتاجية) اللي في تعريف efficiency، مو appropriate."},{"i":2,"mis":"gen.vocab","note":"متوقَّع = projected، كلمة ثانية من نفس الدرس."},{"i":3,"mis":"gen.vocab","note":"معقّد = complex، مو appropriate."}],"tests":["appropriate","effectiveness"]},{"n":120,"lo":"LO1-1","sec":"MGT102-CH1-S1","type":"vocab","topic":"vocab","stem":"What does the word minimize mean? (as in: efficient managers minimize the input resources they use)","options":["يقلّل لأدنى حد","يزيد لأقصى حد","يراقب باستمرار","يوزّع بالتساوي"],"answer":0,"why":"minimize = يقلّل لأدنى حد (من min يعني أقل شي). والمنظمة الكفؤة تقلّل الموارد المُدخَلة أو الوقت لنفس الإنتاج.","wrong":[{"i":1,"mis":"gen.vocab","note":"يزيد لأقصى حد = maximize، عكس minimize بالضبط."},{"i":2,"mis":"gen.vocab","note":"يراقب = monitor، كلمة ثانية من الدرس."},{"i":3,"mis":"gen.vocab","note":"يوزّع = distribute، ما لها علاقة بـ minimize."}],"tests":["minimize","efficiency"]},{"n":201,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"term","topic":"controlling-definition","stem":"Which managerial function is defined as evaluating how well an organization is achieving its goals and taking action to maintain or improve performance?","options":["Planning","Controlling","Organizing","Leading"],"answer":1,"why":"Controlling = تقيّم قد إيش المنظمة قاعدة تحقق أهدافها، وتاخذ إجراء عشان تحافظ على الأداء أو تحسّنه. الكلمة اللي تفضحها: evaluating + improve performance.","wrong":[{"i":0,"mis":"c1.plan-vs-control","note":"كلمة goals تسحبك للتخطيط، بس التخطيط يختار الأهداف، مو يقيّم هل تحققت."},{"i":2,"mis":"gen.neighbor","note":"التنظيم يرتّب علاقات العمل والأقسام، وما فيه تقييم أداء ولا تصحيح."},{"i":3,"mis":"gen.neighbor","note":"القيادة توضيح رؤية وتحميس موظفين، مو قياس نتائج وتصحيحها."}],"tests":["controlling","corrective action"]},{"n":202,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"term","topic":"organizational-structure","stem":"A formal system of task and reporting relationships that coordinates and motivates organizational members so they work together to achieve organizational goals is called:","options":["The organizing function","Organizational leadership","Organizational structure","An organizational department"],"answer":2,"why":"التعريف يبدأ بـ «A formal system» يعني نظام رسمي لعلاقات المهام ومين يرفع تقريره لمين. هذا organizational structure، وهو ناتج organizing مو العملية نفسها.","wrong":[{"i":0,"mis":"gen.neighbor","note":"قريب مرة، بس organizing هو «العملية» اللي تهيكل العلاقات، والتعريف هنا يوصف «النظام الرسمي» اللي يطلع منها."},{"i":1,"mis":"gen.keyword","note":"كلمة coordinate موجودة في تعريف leadership بعد، بس القيادة تأثير وإقناع، مو نظام رسمي للمهام."},{"i":3,"mis":"gen.neighbor","note":"القسم مجموعة ناس بمهارات متشابهة، مو نظام علاقات مهام وتبعية."}],"tests":["organizational structure","organizing"]},{"n":203,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"term","topic":"disseminator-role","stem":"Which of Mintzberg's roles involves informing employees about changes in the external and internal environments that will affect them, and communicating the organization's vision and purpose to them?","options":["Spokesperson","Monitor","Disseminator","Disturbance handler"],"answer":2,"why":"Disseminator ينشر المعلومات «لداخل» الشركة: يبلّغ الموظفين بالتغيّرات ويوصّل لهم الرؤية والغرض. المفتاح: inform employees.","wrong":[{"i":0,"mis":"c1.role-activity","note":"المتحدث الرسمي يكلّم «برا» الشركة زي حملة إعلانية أو خطاب للمجتمع المحلي، مو الموظفين."},{"i":1,"mis":"c1.role-activity","note":"Monitor «يراقب» التغيّرات في البيئة ويقيّم أداء المديرين، بس مو هو اللي يبلّغ الموظفين فيها."},{"i":3,"mis":"gen.keyword","note":"عبارة external and internal environments موجودة في صف Disturbance handler بعد، بس هو يتحرك بسرعة يحل مشكلة مفاجئة، مو يبلّغ الموظفين ويوصّل لهم الرؤية."}],"tests":["disseminator","informational roles","spokesperson","monitor","disturbance handler"]},{"n":204,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"term","topic":"leadership-definition","stem":"According to the textbook, when managers use their power, personality, influence, persuasion, and communication skills to coordinate people and groups so their efforts are in harmony, this is called:","options":["Leadership","Organizing","Liaison","Dissemination"],"answer":0,"why":"Leadership = المدير يستخدم خمس أدوات تأثير (power, personality, influence, persuasion, communication skills) عشان ينسّق الناس وجهودهم تمشي مع بعض. أدوات تأثير وإقناع = قيادة.","wrong":[{"i":1,"mis":"c1.org-vs-lead","note":"التنظيم يرتّب الناس في هيكل رسمي وأقسام، مو بالشخصية والإقناع."},{"i":2,"mis":"gen.keyword","note":"كلمة coordinate تسحبك لـ liaison، بس هذا دور عند Mintzberg ينسّق بين مديري الأقسام ويبني تحالفات مع منظمات ثانية."},{"i":3,"mis":"gen.keyword","note":"communication skills تذكّرك بدور disseminator (نشر المعلومات)، بس هذا ينقل معلومات للموظفين، مو قيادة بالتأثير."}],"tests":["leadership","leading","liaison","disseminator"]},{"n":205,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"concept","topic":"function-outcomes","stem":"According to the textbook, what is an outcome of the leading function?","options":["A highly motivated and committed workforce","The creation of an organizational structure","The ability to measure performance accurately","A chosen set of goals and the strategies to reach them"],"answer":0,"why":"الكتاب يقول: من نواتج leadership قوة عاملة متحمسة وملتزمة (highly motivated and committed workforce). القيادة تحميس وتأثير، فالناتج ناس متحمسين وملتزمين.","wrong":[{"i":1,"mis":"c1.function-outcomes","note":"هذا ناتج organizing: الهيكل التنظيمي يطلع من ترتيب الأقسام وخطوط السلطة، مو من القيادة."},{"i":2,"mis":"c1.function-outcomes","note":"القياس الدقيق للأداء ناتج controlling، مو القيادة."},{"i":3,"mis":"c1.function-outcomes","note":"اختيار الأهداف والاستراتيجيات شغل planning، مو ناتج القيادة."}],"tests":["leading","leadership","organizational structure","controlling"]},{"n":206,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"concept","topic":"controlling-evaluates-functions","stem":"Which statement about the controlling function is true according to the textbook?","options":["It is the function in which managers select the goals and strategies the organization will pursue.","It is the function in which managers set up the task and authority relationships among people.","It helps managers judge how well they themselves perform planning, organizing, and leading.","It checks how individual employees perform, but not departments or the organization as a whole."],"answer":2,"why":"الكتاب يقول: controlling يساعد المدير يقيّم أداءه هو في الوظائف الثلاث الثانية (planning, organizing, leading) وياخذ إجراء تصحيحي. والرقابة تتابع أداء الأفراد والأقسام والمنظمة كلها، مو الموظفين بس.","wrong":[{"i":0,"mis":"c1.plan-vs-control","note":"اختيار الأهداف والاستراتيجيات هذا planning؛ الرقابة تقيس هل تحققت، ما تختارها."},{"i":1,"mis":"gen.neighbor","note":"الوصفين في Figure 1.2 يبدون بـ Establish، بس task and authority relationships حق organizing، والرقابة تبني أنظمة قياس ومتابعة."},{"i":3,"mis":"gen.partial","note":"الرقابة تتابع أداء الأفراد والأقسام والمنظمة كلها، فلو وقفت عند الموظفين أخذت نص القائمة بس."}],"tests":["controlling","corrective action","monitoring individuals, departments, and the organization"]},{"n":207,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"concept","topic":"mintzberg-chaotic-work","stem":"According to the textbook's discussion of Henry Mintzberg's research, which statement describes managerial work?","options":["It is often chaotic, with snap decisions based on intuition and experience.","It is an orderly process in which managers carefully weigh all information before deciding.","It can be fully described by four functions that managers perform in a fixed order.","It follows a steady routine in which managers deal with one problem at a time."],"answer":0,"why":"Mintzberg من أوائل اللي بيّنوا إن الإدارة كثير تكون فوضوية (chaotic)، والمدير ياخذ snap decisions يعني قرارات لحظية معتمد على الحدس (intuition) والخبرة، بدل ما يحلّل كل تفصيلة.","wrong":[{"i":1,"mis":"gen.reversed","note":"هذي الصورة «المرتبة» اللي Mintzberg جا يعارضها، يعني عكس اللي أثبته."},{"i":2,"mis":"c1.theorists","note":"الوظائف الأربع فكرة Fayol مو Mintzberg، و Mintzberg طلع بعشرة أدوار."},{"i":3,"mis":"gen.reversed","note":"الكتاب يقول المديرين يتعاملون مع مشاكل كثيرة في نفس الوقت (simultaneously)، مو وحدة وحدة بروتين ثابت."}],"tests":["henry mintzberg","chaotic management","snap decisions","intuition"]},{"n":208,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"scenario","topic":"planning-three-steps","stem":"Nora owns a chain of cafés in Madinah. She decides the chain will aim to double its delivery sales next year, chooses a partnership with a delivery app as the way to get there, and decides how much budget and staff time each branch will give to delivery. Which managerial function is Nora performing?","options":["Organizing","Controlling","Planning","Leading"],"answer":2,"why":"هدف (تضاعف مبيعات التوصيل) بعدين استراتيجية (شراكة مع تطبيق توصيل) بعدين توزيع الموارد (الميزانية ووقت الموظفين). هذي الخطوات الثلاث للـ planning بالترتيب.","wrong":[{"i":0,"mis":"c1.plan-vs-organize","note":"توزيع الميزانية والوقت يوهمك إنه تنظيم، بس الكتاب يحط «how to allocate resources» الخطوة الثالثة في planning."},{"i":1,"mis":"c1.plan-vs-control","note":"صح فيه أهداف في القصة، بس نورة تختارها، ما تقيس هل تحققت."},{"i":3,"mis":"gen.neighbor","note":"ما فيه تحميس موظفين ولا رؤية ملهمة، كله قرارات أهداف وموارد."}],"tests":["planning","strategy","three steps of planning"]},{"n":209,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"scenario","topic":"organizing-vs-leading","stem":"The new director of a hospital in Riyadh groups the nurses into units by type of care, appoints a head nurse for each unit, and decides that every head nurse will report to the director of nursing. Which managerial function is the director performing?","options":["Leading","Planning","Controlling","Organizing"],"answer":3,"why":"تقسيم الناس لوحدات حسب نوع الشغل + تحديد مين يرفع تقريره لمين = task and reporting relationships وخطوط السلطة. هذا organizing، وناتجه organizational structure.","wrong":[{"i":0,"mis":"c1.org-vs-lead","note":"الاثنين يتعاملون مع الناس، بس القيادة تحميس وإلهام، وهنا المدير يبني هيكل رسمي."},{"i":1,"mis":"gen.neighbor","note":"ما اختار أهداف ولا استراتيجيات، هو رتّب العلاقات بين الناس."},{"i":2,"mis":"gen.neighbor","note":"ما فيه قياس أداء ولا مقارنة بمعايير ولا تصحيح."}],"tests":["organizing","organizational structure"]},{"n":210,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"scenario","topic":"leading-vision","stem":"At a staff meeting, the manager of a telecom company in Dammam shares a short, inspiring statement of what the company wants to become. She then shows each team how its daily work helps reach that future, and the employees leave the meeting energized. Which managerial function is she mainly performing?","options":["Planning","Leading","Organizing","Controlling"],"answer":1,"why":"عبارة قصيرة وملهمة عن مستقبل الشركة = vision، وتوضيح دور كل فريق وتحميسهم = energize and enable. هذا تعريف leading بالضبط.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الرؤية تبان كأنها تخطيط، بس الكتاب يحط «توضيح الرؤية وتحميس الموظفين» تحت leading."},{"i":2,"mis":"c1.org-vs-lead","note":"ما قسّمت أحد على أقسام ولا حدّدت مين يرفع لمين، هي حمّستهم ووضّحت لهم دورهم."},{"i":3,"mis":"gen.neighbor","note":"ما قاست أداء ولا صحّحت شي، الاجتماع كله رؤية وتحميس."}],"tests":["leading","vision"]},{"n":211,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"scenario","topic":"figurehead-vs-leader","stem":"The CEO of a bank in Riyadh cuts the ribbon to open the bank's new head office. In a short speech at the ceremony, she reminds all staff of the ethical rules they must follow when dealing with customers and suppliers. According to Mintzberg, which role is she playing?","options":["Leader","Figurehead","Spokesperson","Entrepreneur"],"answer":1,"why":"قص الشريط لافتتاح مقر جديد وإعلان المبادئ الأخلاقية اللي يمشي عليها الموظفين مع الزباين والموردين = Figurehead، دور رمزي من الأدوار interpersonal. الاثنين مكتوبين تحت Figurehead في Table 1.1.","wrong":[{"i":0,"mis":"c1.role-activity","note":"كلمة must follow تحسّسك إنها أوامر، بس Leader يعطي أوامر شغل مباشرة ويكون قدوة ويحشد الدعم، أما الافتتاح وإعلان المبادئ فدور رمزي = Figurehead."},{"i":2,"mis":"c1.role-activity","note":"فيه خطاب فتحسبه المتحدث الرسمي، بس Spokesperson يكلّم برا الشركة زي المجتمع المحلي أو حملة إعلانية، وهنا الكلام للموظفين عن الأخلاق."},{"i":3,"mis":"c1.role-activity","note":"افتتاح مقر جديد يبان توسّع، بس Entrepreneur يرصد موارد لمنتجات مبتكرة أو يقرر التوسّع دولياً، وهي هنا بس تقص الشريط."}],"tests":["figurehead","leader","interpersonal roles","spokesperson","entrepreneur"]},{"n":212,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"figure","topic":"figure-1-2-text-and-sequence","stem":"Look at Figure 1.2. Find the function described as 'Establish task and authority relationships that allow people to work together to achieve organizational goals.' Following the arrows, which function comes right after it?","img":"img/mgt102/figure-1-2.png","options":["Planning","Leading","Controlling","Organizing"],"answer":1,"why":"الوصف «task and authority relationships» مكتوب في دائرة Organizing، والسهم من Organizing رايح لـ Leading. الدورة كاملة: Planning بعدين Organizing بعدين Leading بعدين Controlling وترجع لـ Planning.","wrong":[{"i":0,"mis":"gen.neighbor","note":"لو حسبت الوصف لـ Controlling (الاثنين يبدون بـ Establish) أو قريت السهم بالعكس بيطلع لك Planning، بس task and authority حق Organizing واللي بعدها Leading."},{"i":2,"mis":"c1.org-vs-lead","note":"لو حسبت الوصف لـ Leading عشان «work together» بيطلع لك Controlling، بس Leading وصفها Motivate, coordinate, and energize، و task and authority حق Organizing."},{"i":3,"mis":"gen.vocab","note":"هذا اسم الدائرة نفسها، بس السؤال يبي اللي «بعدها» (comes right after it) حسب السهم."}],"tests":["four functions of management","sequence of functions","organizing","figure 1.2 descriptions"]},{"n":213,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"figure","topic":"mintzberg-role-category","stem":"Look at Table 1.1. A manager works with suppliers, distributors, and labor unions to reach agreements about the quality and price of resources. Which specific role and type of role does the table give for this activity?","img":"img/mgt102/table-1-1.png","options":["Liaison — Interpersonal","Negotiator — Interpersonal","Resource allocator — Decisional","Negotiator — Decisional"],"answer":3,"why":"في الجدول، التعامل مع الموردين والموزعين والنقابات عشان اتفاقات الجودة والسعر = Negotiator، ومكتوب تحت Decisional. لا يغرّك إنه يتعامل مع ناس، مو interpersonal.","wrong":[{"i":0,"mis":"c1.role-activity","note":"Liaison ينسّق بين مديري الأقسام ويبني تحالفات بين منظمات، مو مفاوضات أسعار مع موردين ونقابات."},{"i":1,"mis":"c1.role-category","note":"الدور صح بس الفئة غلط؛ Negotiator في الجدول تحت Decisional مو Interpersonal."},{"i":2,"mis":"c1.role-activity","note":"Resource allocator يوزّع الموارد بين الأقسام ويحدد الميزانيات، ما يفاوض جهات برا."}],"tests":["negotiator","decisional roles","interpersonal roles","liaison","resource allocator"]},{"n":214,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"list","topic":"mintzberg-role-count","stem":"How many specific managerial roles did Mintzberg identify, and into how many types did he group them?","options":["10 roles in 4 types","9 roles in 3 types","10 roles in 3 types","12 roles in 4 types"],"answer":2,"why":"Mintzberg حدّد 10 أدوار في 3 فئات: 4 decisional + 3 interpersonal + 3 informational. احفظها 4/3/3.","wrong":[{"i":0,"mis":"gen.detail","note":"رقم 4 جاك من الوظائف الأربع أو من عدد أدوار decisional، بس الفئات ثلاث بس."},{"i":1,"mis":"gen.detail","note":"افترضت كل فئة فيها 3، بس decisional فيها 4، فالمجموع 10."},{"i":3,"mis":"gen.detail","note":"حسبت 4 فئات زي الوظائف الأربع وفي كل وحدة 3 أدوار، بس الفئات 3 والأدوار 10."}],"tests":["henry mintzberg","managerial roles","decisional roles","interpersonal roles","informational roles"]},{"n":215,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"people","topic":"fayol-vs-mintzberg","stem":"According to the textbook, who first outlined the four managerial functions, and who identified the ten managerial roles?","options":["Henri Fayol outlined the functions; Henry Mintzberg identified the roles.","Henry Mintzberg outlined the functions; Henri Fayol identified the roles.","Henri Fayol outlined the functions and also identified the roles.","Henry Mintzberg outlined the functions and also identified the roles."],"answer":0,"why":"Fayol (الفرنسي) = الوظائف الأربع في كتابه General and Industrial Management. Mintzberg (أستاذ في McGill) = الأدوار العشرة بعد ما راقب المديرين ساعة بساعة. فايول = وظائف، مينتزبيرغ = أدوار.","wrong":[{"i":1,"mis":"c1.theorists","note":"قلبت الاسمين؛ Henri و Henry متشابهين وهذا هو الفخ."},{"i":2,"mis":"c1.theorists","note":"Fayol صح في الوظائف، بس الأدوار العشرة مو له، هذي لـ Mintzberg."},{"i":3,"mis":"c1.theorists","note":"Mintzberg صح في الأدوار ومراقبة المديرين، بس الوظائف الأربع أول من وصفها Fayol."}],"tests":["henri fayol","henry mintzberg","four functions of management","managerial roles"]},{"n":216,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"tf","topic":"managers-right-half-the-time","stem":"According to the textbook, many managers claim they are doing a good job if their decisions are right only about half of the time.","options":["True","False"],"answer":0,"why":"صح. الكتاب يقول شغل المدير معقّد ومليان مسؤوليات صعبة، فكثير من المديرين يعتبرون نفسهم زينين لو كانوا صح نص المرات بس (right just half of the time). وهذا رقم يجي في الاختبار.","wrong":[{"i":1,"mis":"gen.detail","note":"نص المرات يبان قليل فتحسب الجملة غلط، بس هذا الرقم نفسه اللي في الكتاب، عشان الإدارة فوضوية وقراراتها سريعة."}],"tests":["right just half of the time","chaotic management"]},{"n":217,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"vocab","topic":"vocab-allocate","stem":"In the sentence 'The school received a small grant, so the principal had to allocate the money among its three sports teams,' the word allocate most nearly means:","options":["save and keep for later","measure and check","divide and give out","increase and raise"],"answer":2,"why":"allocate = يوزّع أو يخصّص: تقسّم الفلوس أو الناس على أكثر من جهة. والدليل في الجملة: among its three sports teams يعني «بين» ثلاث فرق.","wrong":[{"i":0,"mis":"gen.vocab","note":"الحفظ معناه keep، والجملة تتكلم عن توزيع الفلوس «بين» الفرق."},{"i":1,"mis":"gen.vocab","note":"القياس والتحقق هذا measure و check، مو allocate."},{"i":3,"mis":"gen.vocab","note":"الزيادة معناها increase، و allocate ما يعني تكبّر الفلوس، يعني تقسّمها."}],"tests":["allocate"]},{"n":218,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"vocab","topic":"vocab-chaotic","stem":"In the sentence 'When the fire alarm rang, the office became chaotic: people ran in every direction and nobody knew what to do,' the word chaotic most nearly means:","options":["calm and carefully planned","disorganized and confused","slow and repetitive","busy but well organized"],"answer":1,"why":"chaotic = فوضوي، ما فيه ترتيب. والدليل في الجملة: people ran in every direction and nobody knew what to do.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا عكس المعنى تماماً؛ الناس تركض في كل اتجاه، فمستحيل يكون هادي ومرتب."},{"i":2,"mis":"gen.vocab","note":"ما له علاقة بالبطء، بالعكس الجملة فيها ركض وارتباك."},{"i":3,"mis":"gen.vocab","note":"الزحمة تشبه الفوضى، بس well organized عكس chaotic تماماً."}],"tests":["chaotic"]},{"n":219,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"vocab","topic":"vocab-corrective","stem":"What does the word 'corrective' mean?","options":["تقييمي","تحفيزي","تصحيحي","رسمي"],"answer":2,"why":"corrective = تصحيحي، من correct يعني يصلّح. و corrective action هي بصمة وظيفة controlling.","wrong":[{"i":0,"mis":"gen.vocab","note":"evaluate (يقيّم) تجي جنبها دايم في controlling، بس corrective هي التصحيح اللي بعد التقييم."},{"i":1,"mis":"gen.vocab","note":"التحفيز كلمته motivate أو energize، وهذي من leading."},{"i":3,"mis":"gen.vocab","note":"رسمي معناها formal، كلمة ثانية من الدرس."}],"tests":["corrective"]},{"n":220,"lo":"LO1-2","sec":"MGT102-CH1-S2","type":"vocab","topic":"vocab-articulate","stem":"What does the verb 'articulate' mean?","options":["يقيس بدقة","يعبّر بوضوح","يرتّب الأقسام","يختار الأهداف"],"answer":1,"why":"articulate = يقول الفكرة بكلام واضح الناس تفهمه. في تعريف leading: المدير articulates a clear vision يعني يوضّح الرؤية.","wrong":[{"i":0,"mis":"gen.vocab","note":"يقيس بدقة هذا measure accurately، من controlling."},{"i":2,"mis":"gen.vocab","note":"ترتيب الأقسام هذا organizing، مو معنى articulate."},{"i":3,"mis":"gen.vocab","note":"يختار = select، من تعريف planning، بس articulate معناها يعبّر بوضوح."}],"tests":["articulate"]},{"n":301,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"term","topic":"top-manager-definition","stem":"According to the book, a top manager is a manager who:","options":["supervises first-line managers and is responsible for finding the best way to use resources to achieve goals","establishes organizational goals, decides how departments should interact, and monitors middle managers","is responsible for the daily supervision of nonmanagerial employees who produce the goods and services","evaluates whether organizational goals are appropriate and suggests to senior managers how to change them"],"answer":1,"why":"تعريف الكتاب للـ top manager ثلاث أشياء: يحدّد أهداف المنظمة (establishes)، يقرّر كيف الأقسام تتعامل مع بعض، ويراقب أداء الـ middle managers. الكلمة المفتاح establish يعني يحدّد، مو suggest يعني يقترح.","wrong":[{"i":0,"mis":"c1.level-duties","note":"هذا تعريف الـ middle manager بالحرف: يشرف على الخط الأول ويدوّر أحسن طريقة لاستخدام الموارد."},{"i":2,"mis":"c1.level-duties","note":"الإشراف اليومي على الموظفين غير الإداريين شغل الـ first-line manager (المشرف)، مو الإدارة العليا."},{"i":3,"mis":"c1.level-duties","note":"تقييم الأهداف واقتراح تغييرها شغل الـ middle manager، والـ top هو اللي يحدّدها (establish)."}],"tests":["top manager","middle manager","first-line manager"]},{"n":302,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"term","topic":"technical-skills-definition","stem":"The job-specific knowledge and techniques that a person needs to perform an organizational role are called:","options":["Conceptual skills","Human skills","Technical skills","Core competency"],"answer":2,"why":"كلمة job-specific (خاصة بالوظيفة) تعني technical skills على طول، زي مهارة المحاسبة أو الطبخ أو التصنيع. هذا تعريف الكتاب على الهامش.","wrong":[{"i":0,"mis":"c1.skills-swap","note":"الـ conceptual هي تحليل الموقف والتفريق بين السبب والنتيجة، مو معرفة خاصة بوظيفة معيّنة."},{"i":1,"mis":"c1.skills-swap","note":"الـ human skills عن فهم سلوك الناس والمجموعات وقيادتهم، ما لها دخل بتقنيات الوظيفة."},{"i":3,"mis":"c1.dept-core","note":"الـ core competency مهارات ومعرفة قسم كامل تخلّي الشركة تتفوّق على منافسيها، مو مهارة شخص عشان يأدّي دوره."}],"tests":["technical skills"]},{"n":303,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"term","topic":"core-competency-definition","stem":"The specific set of departmental skills, knowledge, and experience that allows one organization to outperform another is called a:","options":["Department","Competitive advantage","Technical skill","Core competency"],"answer":3,"why":"المفتاح: set of departmental skills, knowledge, and experience يعني core competency، زي Dell في materials management و Google في R&D. والـ competitive advantage هي النتيجة اللي تجي منها.","wrong":[{"i":0,"mis":"c1.dept-core","note":"الـ department هو مجموعة الناس نفسهم، مو المهارات اللي تخلّي الشركة تتفوّق."},{"i":1,"mis":"c1.dept-core","note":"كلمة outperform تغرّك، بس الـ competitive advantage هي النتيجة، والسؤال يوصف مجموعة مهارات القسم نفسها."},{"i":2,"mis":"gen.neighbor","note":"الـ technical skill مهارة وظيفة لشخص واحد، والتعريف هنا عن مهارات قسم كامل تتفوّق فيها الشركة على غيرها."}],"tests":["core competency","competitive advantage","department"]},{"n":304,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"term","topic":"top-management-team","stem":"A group made up of the CEO, the COO, and the vice presidents most responsible for achieving organizational goals is called the:","options":["Top management team","Self-managed work team","Hierarchy of authority","Board of directors"],"answer":0,"why":"الـ CEO مع الـ COO ونواب الرئيس (vice presidents) يساوون top management team. وبناء فريق إدارة عليا يشتغل بسلاسة همّ أساسي (a central concern) من هموم الـ CEO.","wrong":[{"i":1,"mis":"gen.keyword","note":"اخترتها عشان كلمة team، بس الـ self-managed work team موظفين يديرون شغلهم بنفسهم، مو CEO و COO ونواب رئيس."},{"i":2,"mis":"gen.neighbor","note":"الـ hierarchy of authority هو ترتيب المستويات من فوق لتحت، مو مجموعة محدّدة من كبار المديرين."},{"i":3,"mis":"gen.neighbor","note":"مجلس الإدارة يراقب أداء الشركة من فوق، بس الـ top management team هو الـ CEO والـ COO ونواب الرئيس اللي يشتغلون على الأهداف."}],"tests":["top management team","chief executive officer (ceo)","chief operating officer (coo)","vice presidents"]},{"n":305,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"concept","topic":"why-departments","stem":"According to the book, why are managers and employees with similar job-specific skills grouped into the same department?","options":["Because top managers can then spend most of their time leading and controlling each group","Because each department then needs only first-line managers, not middle or top managers","Because employees can learn from each other and grow more skilled and productive","Because managers in one department then rely on technical skills rather than human or conceptual ones"],"answer":2,"why":"جزء كبير من شغل المدير: يراقب ويدرّب ويشرف على الموظفين عشان مهاراتهم التخصصية تزيد، وهذا أسهل لما المتشابهين يكونون في قسم واحد لأنهم يتعلّمون من بعض ويصيرون أمهر وأكثر إنتاجية.","wrong":[{"i":0,"mis":"c1.fig14-time","note":"مقلوب: الـ top يقضون أغلب وقتهم في planning و organizing، والتقسيم للأقسام عشان الناس يتعلّمون من بعض."},{"i":1,"mis":"c1.dept-core","note":"بالعكس، داخل كل قسم فيه الثلاث مستويات كلها: first-line و middle و top."},{"i":3,"mis":"c1.skills-swap","note":"الكتاب يقول المدير يحتاج الثلاث مهارات كلها، وغياب وحدة بس ممكن يودّي للفشل."}],"tests":["department","technical skills"]},{"n":306,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"concept","topic":"all-three-skills","stem":"Which statement about managerial skills is true according to the book?","options":["Human skills are natural talents, so they cannot be learned through education or training","Top managers require the best technical skills because their main tasks are planning and organizing","A person with strong technical skills will know how to manage a new business successfully","Effective managers need all three kinds of skills, and lacking even one can lead to failure"],"answer":3,"why":"الكتاب واضح: المدير الفعّال يحتاج الثلاث (conceptual و human و technical)، وغياب نوع واحد بس ممكن يودّي للفشل. وانتبه لكلمات مطلقة زي cannot و will.","wrong":[{"i":0,"mis":"gen.absolute","note":"الكتاب يقول الـ human skills تتعلّم بالتعليم والتدريب وتتطوّر بالخبرة، فكلمة cannot غلط."},{"i":1,"mis":"c1.top-conceptual","note":"الـ top managers يحتاجون أفضل conceptual skills (مو technical) لأن شغلهم الأساسي planning و organizing."},{"i":2,"mis":"c1.skills-swap","note":"مثال الكتاب بالعكس: اللي عنده مهارة فنية ويفتح مشروع مو شرط يعرف يديره، لأنه غالباً ناقصه conceptual و human."}],"tests":["conceptual skills","human skills","technical skills"]},{"n":307,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"concept","topic":"time-on-functions-by-level","stem":"According to the book, what happens to the time a manager spends on planning and organizing as he moves up the hierarchy?","options":["It decreases, because top managers spend most of their time leading and controlling","It increases, because these functions are crucial to long-term organizational performance","It stays the same, because managers at every level perform all four functions equally","It increases for planning but decreases for organizing, because top managers do not organize"],"answer":1,"why":"القاعدة: كل ما صعد المدير في الهرم زاد وقته في planning و organizing، لأنها الوظائف اللي تحدّد أداء المنظمة على المدى الطويل. وكل ما نزل زاد وقته في leading و controlling.","wrong":[{"i":0,"mis":"c1.fig14-time","note":"هذا مقلوب: الـ leading و controlling تزيد كل ما نزلت تحت، مو فوق."},{"i":2,"mis":"gen.absolute","note":"صح كل المستويات تسوي الأربع وظائف، بس مو بالتساوي؛ الأهمية النسبية تعتمد على مكان المدير في الهرم."},{"i":3,"mis":"gen.partial","note":"الكتاب يقول الاثنين مع بعض (planning و organizing) يزيدون، والـ top managers يقضون أغلب وقتهم فيهم."}],"tests":["planning","organizing","relative time on managerial functions","top manager"]},{"n":308,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"scenario","topic":"first-line-manager","stem":"Nora leads a team of cashiers at a supermarket branch in Jeddah. Every day she assigns their shifts, checks their work at the counters, and solves problems as they come up. None of the people she supervises are managers. Nora is best described as a:","options":["Middle manager","Nonmanagerial employee","First-line manager","Top manager"],"answer":2,"why":"Nora تشرف يومياً على موظفين مو مديرين (الكاشيرات)، يعني first-line manager، ويسمّونهم supervisors. المفتاح: daily supervision واللي تحتها موظفين غير إداريين.","wrong":[{"i":0,"mis":"c1.level-duties","note":"الـ middle manager يشرف على مديرين الخط الأول، و Nora ما تحتها أي مدير."},{"i":1,"mis":"gen.keyword","note":"الموظفين غير الإداريين هم الكاشيرات اللي تحتها؛ هي تشرف عليهم فهي مديرة."},{"i":3,"mis":"c1.level-duties","note":"الـ top manager مسؤول عن كل الأقسام ويحدّد أهداف المنظمة، مو يوزّع شفتات فرع واحد."}],"tests":["first-line manager","supervisors","nonmanagerial employees"]},{"n":309,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"scenario","topic":"middle-vs-top-manager","stem":"At a hospital in Riyadh, Majed chooses which supervisors will run a new project and tells senior management that one of this year's goals is unrealistic. His boss, Dr. Huda, is responsible for the performance of all the hospital's departments, sets the hospital's goals, and decides how the departments should work together. Which statement is correct?","options":["Majed is a top manager and Dr. Huda is a middle manager","Majed is a first-line manager and Dr. Huda is a middle manager","Majed and Dr. Huda are top managers, since each of them deals with goals","Majed is a middle manager and Dr. Huda is a top manager"],"answer":3,"why":"Majed يختار المشرفين ويقترح تغيير الأهداف، يعني middle manager. Dr. Huda مسؤولة عن كل الأقسام (cross-departmental responsibility) وتحدّد الأهداف، يعني top manager. الفرق: يقترح ≠ يحدّد.","wrong":[{"i":0,"mis":"c1.level-duties","note":"قلبت المستويين: اللي يقترح تغيير الأهداف هو الأوسط، واللي يحدّدها ومسؤول عن كل الأقسام هو الأعلى."},{"i":1,"mis":"c1.level-duties","note":"Majed يختار مشرفين، يعني يشرف على الخط الأول، فهو أعلى من first-line."},{"i":2,"mis":"gen.keyword","note":"كلمة goals موجودة عند الاثنين، بس Majed يقترح بس، والتحديد والمسؤولية عن كل الأقسام للـ top."}],"tests":["middle manager","top manager","cross-departmental responsibility"]},{"n":310,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"scenario","topic":"conceptual-skills","stem":"Sales at a chain of cafés in Madinah fell for three months. Most staff blamed the coffee beans, but the regional director compared sales, prices, and customer visits across all branches and found that the drop began the week a new competitor opened nearby with lower prices. Which type of skill did the director mainly show?","options":["Technical skills","Conceptual skills","Human skills","Decisional skills"],"answer":1,"why":"المدير ما وقف عند أول تفسير؛ جمع الصورة كاملة وشخّص وش السبب الحقيقي للمشكلة ووش النتيجة، وهذا conceptual skills.","wrong":[{"i":0,"mis":"c1.skills-swap","note":"الـ technical skill مهارة شغلة معيّنة زي تحميص القهوة أو المحاسبة، والمدير هنا شخّص سبب المشكلة."},{"i":2,"mis":"c1.skills-swap","note":"الـ human skills عن التعامل مع سلوك الناس وتحفيزهم، وهنا ما فيه تعامل مع الموظفين."},{"i":3,"mis":"c1.role-category","note":"decisional اسم فئة أدوار عند Mintzberg، مو وحدة من المهارات الثلاث (conceptual و human و technical)."}],"tests":["conceptual skills"]},{"n":311,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"scenario","topic":"human-skills","stem":"Dr. Saad, an excellent research engineer at a technology company in Dhahran, was promoted to head his research group. His engineering work is still strong, but his team complains that he cannot communicate with them, motivate them, or turn them into a cohesive team. According to the book, what does Dr. Saad mainly lack?","options":["Human skills","Technical skills","Conceptual skills","A core competency"],"answer":0,"why":"التواصل والتحفيز وتحويل الأفراد لفريق متماسك، هذي human skills. والكتاب نفسه يقول أكبر مشكلة للعالِم أو المهندس اللي ينتقل من البحث للإدارة هي نقص الـ human skills.","wrong":[{"i":1,"mis":"c1.skills-swap","note":"مهارته الهندسية (technical) قوية أصلاً حسب السيناريو، مشكلته مع الناس."},{"i":2,"mis":"c1.skills-swap","note":"الـ conceptual تحليل الموقف والسبب والنتيجة، والشكوى هنا عن تعامله مع الفريق."},{"i":3,"mis":"c1.dept-core","note":"الـ core competency مهارات قسم تخلّي الشركة تتفوّق على منافسيها، مو شي ينقص شخص واحد."}],"tests":["human skills"]},{"n":312,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"figure","topic":"fig-1-3-levels","stem":"Look at Figure 1.3. According to the book, what are the managers in the layer directly above the first-line managers responsible for?","img":"img/mgt102/figure-1-3.png","options":["Daily supervision of the nonmanagerial employees who produce goods and services","Establishing organizational goals and deciding how departments should interact","Finding the best way to organize human and other resources to achieve goals","Leading the top management team as the manager all top managers report to"],"answer":2,"why":"في الهرم، الطبقة اللي فوق First-line managers مباشرة هي Middle managers، وشغلهم يدوّرون أحسن طريقة لتنظيم الموارد البشرية وغيرها عشان تتحقّق الأهداف.","wrong":[{"i":0,"mis":"c1.level-duties","note":"هذا شغل الطبقة اللي تحت (first-line)؛ قريت الشكل من الطبقة الغلط."},{"i":1,"mis":"c1.level-duties","note":"هذا شغل الـ Top managers، وهم فوق الـ middle، مو فوق first-line مباشرة."},{"i":3,"mis":"c1.ceo-coo-tmt","note":"هذا وصف الـ CEO في قمة الهرم، بعيد عن الطبقة اللي فوق first-line."}],"tests":["middle manager","levels of management"]},{"n":313,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"figure","topic":"fig-1-4-time","stem":"Look at Figure 1.4. In the row for first-line managers, which function takes the largest share of their time?","img":"img/mgt102/figure-1-4.png","options":["Planning","Organizing","Controlling","Leading"],"answer":3,"why":"في صف First-line managers أعرض قطعة بفارق كبير هي Leading. وهذا يطابق الكتاب: كل ما نزل المدير في الهرم، زاد وقته في leading و controlling.","wrong":[{"i":0,"mis":"c1.fig14-time","note":"Planning أعرض شي عند Top managers، وعند first-line قطعتها صغيرة."},{"i":1,"mis":"c1.fig14-time","note":"Organizing قطعة متوسطة، وتكبر عند الـ top مو عند الخط الأول."},{"i":2,"mis":"gen.partial","note":"الكتاب يقول leading و controlling يزيدون تحت، بس في الشكل Controlling شريط ضيق؛ الأعرض هو Leading."}],"tests":["leading","first-line manager","relative time on managerial functions"]},{"n":314,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"figure","topic":"fig-1-5-departments","stem":"Look at Figure 1.5. What does the figure show about the marketing and sales department?","img":"img/mgt102/figure-1-5.png","options":["It has its own first-line, middle, and top managers inside it","Its top managers sit above all departments, not inside it","It sits above the manufacturing department in the hierarchy of authority","It is one of the three levels of management in the pyramid"],"answer":0,"why":"الشكل يقسّم الهرم رأسياً لأقسام وأفقياً لمستويات، وشريحة كل قسم (زي Marketing and sales) تمرّ بالثلاث طبقات: top و middle و first-line. يعني داخل كل قسم فيه الثلاث مستويات.","wrong":[{"i":1,"mis":"c1.dept-core","note":"الـ CEO بس اللي فوق الأقسام؛ طبقة Top managers نفسها مقسومة على الأقسام."},{"i":2,"mis":"c1.dept-core","note":"الأقسام في الشكل جنب بعض (شرائح رأسية)، مو فوق بعض؛ اللي فوق بعض هي المستويات بس."},{"i":3,"mis":"c1.dept-core","note":"القسم شريحة رأسية مو طبقة؛ المستويات هي الطبقات الأفقية."}],"tests":["department","levels of management"]},{"n":315,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"list","topic":"three-levels","stem":"According to the book, how many levels of management do organizations normally have?","options":["Four: first-line, middle, and top managers, plus the CEO","Three: first-line managers, middle managers, and top managers","Four: nonmanagerial employees, first-line, middle, and top managers","Three: supervisors, first-line managers, and middle managers"],"answer":1,"why":"المستويات ثلاثة بس: first-line و middle و top. الـ CEO جزء من الـ top (أعلاهم)، والموظفين غير الإداريين مو مستوى إداري أصلاً.","wrong":[{"i":0,"mis":"c1.ceo-coo-tmt","note":"الـ CEO مو مستوى رابع؛ هو أعلى واحد داخل الـ top managers حتى لو Figure 1.3 تحطّه في شريحة لحاله."},{"i":2,"mis":"gen.detail","note":"الموظفين غير الإداريين هم اللي تحت الخط الأول، مو مستوى من مستويات الإدارة."},{"i":3,"mis":"gen.vocab","note":"الـ supervisors هم نفسهم first-line managers (اسم ثاني لهم)، فهذا الاختيار مكرّر وناقصه الـ top."}],"tests":["levels of management","first-line manager","middle manager","top manager","chief executive officer (ceo)","nonmanagerial employees","supervisors"]},{"n":316,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"list","topic":"two-ways-to-group-managers","stem":"According to the book, on what two bases does an organization divide its managers into groups?","options":["By the four functions they perform and by Mintzberg's roles","By level in the hierarchy of authority and by type of skill","By level in the hierarchy and by the time they spend on planning","By type of skill and by their years of formal education"],"answer":1,"why":"الكتاب يقول طريقتين: بالمستوى في هرم السلطة (first-line و middle و top)، وبنوع المهارة يعني الأقسام حسب المهارات والخبرات الخاصة بالوظيفة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"الوظائف الأربع وأدوار Mintzberg أشياء يسويها كل مدير، مو طريقة تقسّم فيها المنظمة مديريها."},{"i":2,"mis":"gen.partial","note":"النص الأول صح (المستوى)، بس الطريقة الثانية نوع المهارة والقسم، مو الوقت اللي يقضيه في التخطيط."},{"i":3,"mis":"gen.partial","note":"نوع المهارة صح، بس الطريقة الثانية هي المستوى في الهرم، مو سنوات الدراسة."}],"tests":["hierarchy of authority","department","levels of management"]},{"n":317,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"tf","topic":"ceo-vs-coo","stem":"According to the textbook, the term chief operating officer (COO) often refers to a top manager who is being prepared to take over the CEO's responsibilities when the current CEO retires or leaves.","options":["True","False"],"answer":0,"why":"صح. الكتاب يقول الـ COO غالباً مدير أعلى يتجهّز (being groomed) عشان ياخذ مسؤوليات الـ CEO لما يتقاعد أو يطلع. أما أعلى مدير في الشركة، اللي كل المديرين الكبار يرجعون له، فهو الـ CEO.","wrong":[{"i":1,"mis":"c1.ceo-coo-tmt","note":"اخترت غلط لأنك حسبت الـ COO هو أعلى مدير — هذا الـ CEO. الـ COO هو اللي يتجهّز يصير CEO."}],"tests":["chief operating officer (coo)","chief executive officer (ceo)"]},{"n":318,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"vocab","topic":"vocab-scrutinize","stem":"In the sentence 'The performance of top managers is continually scrutinized by employees and investors,' the word scrutinized most nearly means:","options":["praised in public","examined very closely","completely ignored","generously rewarded"],"answer":1,"why":"scrutinize يعني يدقّق ويراقب بدقة. الموظفين والمستثمرين يراقبون أداء المدير الأعلى كل حركة.","wrong":[{"i":0,"mis":"gen.vocab","note":"praised يعني يمدحون، والجملة ما فيها مدح، فيها مراقبة دقيقة."},{"i":2,"mis":"gen.vocab","note":"ignored يعني يتجاهلون، وهذا عكس المعنى تماماً."},{"i":3,"mis":"gen.vocab","note":"rewarded يعني يكافئون، ما لها علاقة بمعنى الكلمة."}],"tests":["scrutinize","top manager"]},{"n":319,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"vocab","topic":"vocab-groom","stem":"In the sentence 'Two young doctors at the hospital are being groomed to become department heads in a few years,' the word groomed most nearly means:","options":["cleaned and dressed neatly","blamed for a failure","prepared for a future role","moved to a lower position"],"answer":2,"why":"groom هنا يعني يجهّزون الشخص ويهيّئونه لمنصب أكبر بعدين، والجملة نفسها تقول (to become department heads).","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا معنى groom العادي (يرتّب شكله)، بس هنا معناها يجهّزونه لمنصب أكبر."},{"i":1,"mis":"gen.vocab","note":"blamed يعني يلومونه، ما لها دخل بالمعنى."},{"i":3,"mis":"gen.vocab","note":"بالعكس، اللي يتجهّز يطلع لمنصب أعلى، مو ينزل."}],"tests":["groom"]},{"n":320,"lo":"LO1-3","sec":"MGT102-CH1-S3","type":"vocab","topic":"vocab-ascend","stem":"What does 'ascend' mean?","options":["يصعد / يرتقي","ينزل / يهبط","يراقب / يتابع","يتقاعد / يترك"],"answer":0,"why":"ascend يعني يصعد. والكتاب يقول وقت التخطيط والتنظيم يزيد كل ما المدير ascends the hierarchy يعني يطلع في الهرم.","wrong":[{"i":1,"mis":"gen.vocab","note":"ينزل عكس المعنى بالضبط؛ النزول descend."},{"i":2,"mis":"gen.vocab","note":"يراقب هي monitor، كلمة ثانية من نفس الدرس."},{"i":3,"mis":"gen.vocab","note":"يتقاعد هي retire، مرّت في كلام الـ CEO بس مو هذي الكلمة."}],"tests":["ascend","relative time on managerial functions"]},{"n":321,"lo":"LO1-4","sec":"MGT102-CH1-S3","type":"vocab","topic":"vocab-outperform","stem":"What does 'outperform' mean?","options":["ينافس","يقلّد","يخسر أمام","يتفوّق على"],"answer":3,"why":"outperform يعني يتفوّق على غيره ويسوي أحسن منه. والـ core competency هي اللي تخلّي الشركة outperform its competitors.","wrong":[{"i":0,"mis":"gen.vocab","note":"ينافس هي compete؛ قريبة، بس outperform معناها تغلبه مو بس تنافسه."},{"i":1,"mis":"gen.vocab","note":"يقلّد هي imitate، ما لها علاقة."},{"i":2,"mis":"gen.vocab","note":"يخسر أمام عكس المعنى تماماً."}],"tests":["outperform","core competency"]},{"n":401,"lo":"LO1-5","sec":"MGT102-CH1-S4","type":"term","topic":"empowerment","stem":"In the text, the expansion of employees' knowledge, their tasks, and their decision-making responsibilities is called:","options":["Cross-training","Self-managed work teams","Empowerment","Restructuring"],"answer":2,"why":"Empowerment في الكتاب = توسيع معرفة الموظف ومهامه ومسؤولياته في اتخاذ القرار، وهو نفس اللي درسته: more authority and responsibility. المفتاح decision-making responsibilities يعني الصلاحية، أما knowledge و tasks لحالهم بدون قرار فهذا cross-training.","wrong":[{"i":0,"mis":"gen.partial","note":"cross-training يوسّع مهارات الموظف عشان يسوي مهام كثيرة، بس ما فيه صلاحية قرار، فهو نص التعريف بس."},{"i":1,"mis":"c1.empower-teams","note":"الفرق ذاتية الإدارة مجموعات موظفين تنظّم وتراقب شغلها، والتعريف هنا عن توسيع صلاحيات الموظف نفسه مو عن مجموعة."},{"i":3,"mis":"gen.neighbor","note":"restructuring تقليص للمنظمة بإلغاء وظائف، يعني عكس التوسيع تماماً."}],"tests":["empowerment","cross-training","self-managed work teams","restructuring"]},{"n":402,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"term","topic":"innovation","stem":"According to the text, the process of creating new or improved goods and services, or developing better ways to produce or provide them, is:","options":["Flexibility","Innovation","Speed","Total quality management"],"answer":1,"why":"Innovation = عملية إنشاء سلع وخدمات جديدة أو محسّنة، أو طرق أحسن لإنتاجها أو تقديمها. المفتاح كلمة process of creating new or improved.","wrong":[{"i":0,"mis":"c1.innovation-speed","note":"flexibility يعني قد إيش بسهولة تغيّر طريقة شغلك عشان ترد على المنافسين، مو عملية خلق منتجات جديدة."},{"i":2,"mis":"c1.innovation-speed","note":"speed هو قد إيش بسرعة تنزّل المنتج الجديد للسوق، يعني الوقت مو خلق المنتج نفسه."},{"i":3,"mis":"gen.neighbor","note":"TQM فعلاً فيها ناس يدوّرون طرق أحسن للشغل، بس هي تقنية لبنة الجودة بفرق quality control، مو تعريف الابتكار."}],"tests":["innovation","speed","flexibility","total quality management"]},{"n":403,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"term","topic":"turnaround-management","stem":"In the text, turnaround management refers to:","options":["downsizing a company by eliminating the jobs of large numbers of managers and employees","creating new or improved goods and services, or developing better ways to produce them","creating a new vision for a struggling company through new planning and organizing","choosing teams, a chain of command, and negotiating strategies to respond to a crisis"],"answer":2,"why":"turnaround management = رؤية جديدة لشركة متعثرة (struggling) بنهج جديد في التخطيط والتنظيم عشان تبقى وتزدهر، زي اللي سواه Steve Jobs في Apple. المفتاح: struggling company + new vision.","wrong":[{"i":0,"mis":"c1.turnaround-mix","note":"هذا تعريف restructuring، والتحوّل ممكن يستخدم التقليص كأداة بس هو أوسع: رؤية جديدة كاملة للشركة."},{"i":1,"mis":"gen.neighbor","note":"هذا تعريف innovation، فيه كلمة «جديد» زي التحوّل بس هو عن منتجات وطرق إنتاج مو إنقاذ شركة متعثرة."},{"i":3,"mis":"c1.turnaround-mix","note":"هذي اختيارات crisis management، وهي تحدي ثاني يخص الأزمات العالمية، مو إنقاذ شركة من الإفلاس."}],"tests":["turnaround management","restructuring","innovation","crisis management"]},{"n":404,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"term","topic":"competitive-advantage","stem":"According to the text, competitive advantage is the ability of one organization to:","options":["operate and compete successfully in more than one country instead of only in its home market","outperform others because it uses fewer people and raw materials than they do to make its goods","lower its operating costs by eliminating the jobs of large numbers of managers and employees","outperform others by producing desired goods or services more efficiently and effectively"],"answer":3,"why":"competitive advantage = قدرة المنظمة تتفوّق (outperform) على غيرها لأنها تنتج اللي يبيه الزبون بكفاءة وفعالية أكثر منهم. لازم الكلمتين مع بعض: efficiently and effectively.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا تعريف global organizations، تعمل وتتنافس في أكثر من دولة، بس هذا مو معناه إنها متفوّقة على غيرها."},{"i":1,"mis":"c1.one-e-only","note":"استخدام موارد أقل = efficiency بس، والتعريف يبي الكفاءة والفعالية مع بعض."},{"i":2,"mis":"gen.neighbor","note":"إلغاء الوظائف لتقليل التكاليف هو restructuring من LO1-5، تغيير في الإدارة مو تعريف الميزة التنافسية."}],"tests":["competitive advantage","global organizations","efficiency","restructuring"]},{"n":405,"lo":"LO1-5","sec":"MGT102-CH1-S4","type":"scenario","topic":"restructuring-vs-outsourcing","stem":"A telecom company in Riyadh is still profitable, but its managers want to lower operating costs. They close two product teams, make several departments smaller, and remove one management level, cutting hundreds of jobs of managers and nonmanagerial employees. This change is best described as:","options":["Outsourcing","Restructuring","Empowerment","Turnaround management"],"answer":1,"why":"Restructuring = تقليص المنظمة من الداخل عشان تقل تكاليف التشغيل: تلغي فرق منتجات، تصغّر أقسام، وتشيل مستويات من الهرم. المفتاح: كل شي صار داخل الشركة وما فيه عقد مع شركة ثانية.","wrong":[{"i":0,"mis":"c1.restruct-vs-outsource","note":"الاثنين يوفّرون تكاليف، بس outsourcing يعني تعطي النشاط لشركة ثانية بعقد، وهنا ما فيه أي شركة ثانية."},{"i":2,"mis":"c1.empower-teams","note":"شيل مستوى من الهرم يخلّي الهيكل أسطح فتحسبه تمكين، بس التمكين توسيع صلاحيات الموظف مو إلغاء وظائف."},{"i":3,"mis":"c1.turnaround-mix","note":"التحوّل لشركة متعثرة تجيب CEO جديد برؤية جديدة، وهالشركة لسا رابحة وما فيه رؤية جديدة."}],"tests":["restructuring","downsizing","outsourcing","empowerment","turnaround management"]},{"n":406,"lo":"LO1-5","sec":"MGT102-CH1-S4","type":"scenario","topic":"self-managed-teams-coach","stem":"At a car-parts factory in Dammam, a team of eight workers now organizes its own schedule, supervises its own members, and controls its own work. According to the text, what happens to the role of the team's first-line manager in this situation?","options":["He acts as a coach or mentor who offers advice and guidance","He tells each worker exactly which task to do and when to do it","His position is removed, since a self-managed team needs no manager","He turns into a middle manager who allocates resources among teams"],"answer":0,"why":"الفريق هنا ينظّم ويشرف ويراقب شغله بنفسه = self-managed work team. والكتاب يقول مع هالفرق مدير الخط الأول يصير coach أو mentor: ما يقول لهم وش يسوون، بس ينصح ويوجّه.","wrong":[{"i":1,"mis":"gen.reversed","note":"هذا عكس كلام الكتاب بالضبط، مع الفرق ذاتية الإدارة المدير ما يعطي أوامر تفصيلية."},{"i":2,"mis":"c1.empower-teams","note":"الفريق ياخذ مهام كان يسويها المشرف فتحسب المشرف انشال، بس الكتاب يقول دوره يتغيّر لمدرّب مو ينلغي."},{"i":3,"mis":"c1.level-duties","note":"الكتاب فعلاً يقول middle managers يراقبون الفرق ويقررون توزيع الموارد، بس هذا شغل المدير الأوسط مو اللي يصير لمدير الخط الأول."}],"tests":["self-managed work teams","first-line managers","empowerment"]},{"n":407,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"scenario","topic":"speed-vs-flexibility","stem":"A fashion retailer in Jeddah does not come up with very original designs, but it can take a new clothing line from the design table to its stores in three weeks, while its rivals need six months. Which term from the text names this particular strength?","options":["Innovation","Flexibility","Efficiency","Speed"],"answer":3,"why":"speed في الكتاب = قد إيش بسرعة تنزّل منتجات جديدة للسوق. المفتاح: ثلاث أسابيع مقابل ست شهور، الكلام كله عن الوقت مو عن فكرة المنتج.","wrong":[{"i":0,"mis":"c1.innovation-speed","note":"المنتج جديد فتحسبه ابتكار، بس القصة قالت التصاميم عادية، والميزة هي السرعة في التنزيل."},{"i":1,"mis":"c1.innovation-speed","note":"flexibility = سهولة تغيير طريقة الشغل عشان ترد على المنافسين، وهنا ما فيه تغيير في طريقة الشغل."},{"i":2,"mis":"gen.neighbor","note":"efficiency = تستخدم موارد أقل، والقصة ما تكلمت عن الموارد، تكلمت عن الوقت لين يوصل المنتج للسوق."}],"tests":["speed","flexibility","innovation","efficiency"]},{"n":408,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"scenario","topic":"social-responsibility","stem":"A cement company in Yanbu installs filters to reduce the dust its plant releases, recycles its waste water, gives its workers safe and respectful working conditions, and funds a training center for young people in the town. Its managers say the company owes this to the people its plant affects. According to the text, this shows the company's approach to:","options":["Managing a diverse workforce","Social responsibility","Global crisis management","Total quality management"],"answer":1,"why":"المديرين قالوا إن الشركة عليها واجب تجاه الناس اللي يتأثرون بشغلها، وهذا قلب social responsibility: وش التزامات الشركة تجاه الناس والمجموعات اللي يتأثرون بنشاطها. والكتاب يقول الشركات المسؤولة اجتماعياً تحط أهداف لتقليل الهدر والتلوث، ومعاملة العمال بكرامة واحترام، وتنمية المجتمع، وهذا كله موجود في القصة.","wrong":[{"i":0,"mis":"c1.ethics-csr-diversity","note":"«ظروف عمل آمنة ومحترمة» خلّتك تفكر في التنوّع، بس التنوّع عن معاملة موظفين مختلفين في العمر والجنس والدين بعدل، والقصة ما فيها هذا."},{"i":2,"mis":"gen.keyword","note":"كلمة safe وتقليل الغبار جابت لك الأزمات، بس الشركة هنا تحط أهداف عادية، ما فيه أزمة ولا كارثة تستجيب لها."},{"i":3,"mis":"gen.neighbor","note":"TQM تقنية لتحسين جودة المنتج بفرق quality control، ما لها دخل بتقليل التلوث ودعم المجتمع."}],"tests":["social responsibility","managing a diverse workforce","global crisis management","total quality management"]},{"n":409,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"figure","topic":"building-blocks-figure","stem":"Look at Figure 1.6. Which set lists exactly the four building blocks that the figure shows feeding into competitive advantage?","img":"img/mgt102/figure-1-6.png","options":["Efficiency, effectiveness, quality, and responsiveness to customers","Efficiency, quality, innovation and flexibility, and restructuring","Efficiency, quality, innovation and flexibility, and responsiveness to customers","Quality, innovation and flexibility, responsiveness to customers, and profitability"],"answer":2,"why":"الشكل فيه أربع دوائر، كل وحدة بسهم يدخل على مربع Competitive advantage: Efficiency فوق يسار، Innovation and flexibility فوق يمين، Quality تحت يسار، Responsiveness to customers تحت يمين.","wrong":[{"i":0,"mis":"gen.detail","note":"effectiveness موجودة في تعريف الميزة التنافسية بس مو دائرة في الشكل، وهالخيار ناقصه innovation and flexibility."},{"i":1,"mis":"gen.neighbor","note":"restructuring من تغيّرات LO1-5 هدفه تقليل التكاليف، مو لبنة في Figure 1.6، واللبنة الرابعة هي الاستجابة للعملاء."},{"i":3,"mis":"gen.detail","note":"الربحية مو مكتوبة في الشكل، والناقص هنا efficiency، فدايم ابدأ العد من الدائرة اللي فوق يسار."}],"tests":["building blocks of competitive advantage","competitive advantage","efficiency","quality","innovation and flexibility","responsiveness to customers"]},{"n":410,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"list","topic":"five-challenges","stem":"Which of the following is NOT one of the five major challenges the text lists for managers in today's global environment?","options":["Maintaining ethical standards","Managing a diverse workforce","Utilizing new information systems and technologies","Moving employees into self-managed work teams"],"answer":3,"why":"التحديات الخمس: building a competitive advantage، maintaining ethical standards، managing a diverse workforce، utilizing new information systems and technologies، practicing global crisis management. أما self-managed teams فهي من التغيّرات الحديثة في LO1-5 مو من الخمسة.","wrong":[{"i":0,"mis":"c1.challenges-vs-blocks","note":"الأخلاق هي التحدي الثاني في القائمة، يمكن نسيتها لأنها تجي مع المسؤولية الاجتماعية في نفس العنوان."},{"i":1,"mis":"c1.challenges-vs-blocks","note":"إدارة قوة عاملة متنوّعة هي التحدي الثالث بالنص، فهي من الخمسة أكيد."},{"i":2,"mis":"c1.challenges-vs-blocks","note":"استخدام التقنيات الجديدة هو التحدي الرابع، ومثاله ORION حق UPS."}],"tests":["five major challenges","maintaining ethical standards","managing a diverse workforce","utilizing new technologies","self-managed work teams"]},{"n":411,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"list","topic":"crisis-causes","stem":"Which of the following does the text classify as a NATURAL cause of global crises?","options":["Industrial pollution","The recent global pandemic","Earthquakes","Inattention to employee safety"],"answer":2,"why":"الكتاب يقسم أسباب الأزمات لنوعين: طبيعية (hurricanes, wildfires, earthquakes, famines, diseases) وبشرية (industrial pollution, inattention to employee safety, destruction of habitat, geopolitical tension and terrorism, the recent global pandemic). فالزلازل هي الطبيعية الوحيدة هنا.","wrong":[{"i":0,"mis":"c1.crisis-causes","note":"التلوث الصناعي من صنع الإنسان، فهو من human causes مو الطبيعية."},{"i":1,"mis":"c1.crisis-causes","note":"الجائحة مرض فتحسبها طبيعية زي diseases، بس الكتاب حط «the recent global pandemic» تحت الأسباب البشرية، وهذا فخ مشهور."},{"i":3,"mis":"c1.crisis-causes","note":"إهمال سلامة الموظفين غلط بشري، فهو human cause مو طبيعي."}],"tests":["global crisis management","natural causes","human causes"]},{"n":412,"lo":"LO1-5","sec":"MGT102-CH1-S4","type":"concept","topic":"outsourcing-restructuring-facts","stem":"Which statement about recent changes in management practices is correct according to the text?","options":["Restructuring has no real downsides, because the remaining employees feel more secure in their jobs.","Outsourcing means moving an activity from one department to another department inside the same company.","Outsourcing raises efficiency because lower operating costs free up resources for more effective uses.","The two main factors behind these changes are global competition and the recent global pandemic."],"answer":2,"why":"الكتاب يقول outsourcing يزيد الكفاءة لأنه يخفّض تكاليف التشغيل، فتتحرّر فلوس وموارد تنصرف بطرق أفعل، زي تطوير منتجات جديدة.","wrong":[{"i":0,"mis":"gen.absolute","note":"الكتاب يقول العكس: restructuring ممكن ينزّل معنويات الباقين لأنهم يخافون على وظائفهم، وأحياناً الشركة تقلّص زيادة عن اللزوم."},{"i":1,"mis":"c1.restruct-vs-outsource","note":"outsourcing عقد مع شركة ثانية، عادة برا البلد، مو نقل شغل بين أقسام نفس الشركة."},{"i":3,"mis":"gen.partial","note":"global competition صح، بس السبب الثاني advances in technology، والجائحة الكتاب ذكرها كظرف دفع الشركات تقلّص، مو واحد من السببين."}],"tests":["outsourcing","restructuring","global competition","advances in technology"]},{"n":413,"lo":"LO1-5","sec":"MGT102-CH1-S4","type":"concept","topic":"remote-workers","stem":"Which statement about remote workers is correct according to the text?","options":["They are employees of another company that performs work the organization used to do itself.","They are employees who work from home or another outside workspace on a regular basis.","When companies sent them home in 2020, most firms found that overall productivity fell.","Before the pandemic, about 60% of U.S. workers already worked mainly from home."],"answer":1,"why":"remote workers = موظفين يشتغلون من البيت أو مكان برا المكتب بشكل منتظم (on a regular basis). والكتاب يقول لما راحوا البيوت في 2020 الإنتاجية زادت.","wrong":[{"i":0,"mis":"c1.restruct-vs-outsource","note":"هذا وصف outsourcing، شركة ثانية تسوي الشغل، أما العامل عن بعد فهو موظف في نفس الشركة بس يشتغل برا المكتب."},{"i":2,"mis":"gen.reversed","note":"الكتاب يقول الشركات لقت الإنتاجية الإجمالية ارتفعت، مو نزلت."},{"i":3,"mis":"gen.detail","note":"قبل الجائحة 6% بس كانوا يشتغلون من البيت أساساً، والـ60% رقم استطلاع Pew 2022 عن اللي يفضّلون الشغل عن بعد."}],"tests":["remote workers","outsourcing"]},{"n":414,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"concept","topic":"crisis-management-choices","stem":"Which statement about the challenges managers face in today's global environment is correct according to the text?","options":["Pressure to perform is always harmful to a company, because it pushes managers to act unethically.","Crisis management involves choices such as forming teams for fast decisions and a chain of command.","Responsiveness to customers matters mainly for manufacturers, and very little for service firms.","Companies that have both speed and flexibility are what the text calls global organizations."],"answer":1,"why":"إدارة الأزمات في الكتاب = أربع اختيارات: تسوي فرق تسرّع القرار والتواصل، تحدد chain of command عشان الاستجابة تكون سريعة، تختار الناس الصح يقودون هالفرق ويشتغلون فيها، وتطوّر استراتيجيات تفاوض تحل الخلافات. والخيار الصح ذكر أول اثنين منها.","wrong":[{"i":0,"mis":"gen.absolute","note":"الكتاب يقول الضغط على الأداء ممكن يكون صحي ويخلّي المديرين يدوّرون طرق أحسن، بس الضغط الزايد هو اللي يدفعهم للتصرف غير الأخلاقي، فكلمة always غلط."},{"i":2,"mis":"gen.reversed","note":"العكس: الاستجابة للعملاء مهمة للكل، وخصوصاً منظمات الخدمات زي البنوك والمستشفيات."},{"i":3,"mis":"gen.neighbor","note":"الشركات اللي عندها speed و flexibility اسمها agile competitors، أما global organizations فهي اللي تشتغل وتتنافس في أكثر من دولة."}],"tests":["crisis management","global crisis management","maintaining ethical standards","responsiveness to customers","agile competitors","speed","flexibility","global organizations"]},{"n":415,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"tf","topic":"global-organizations","stem":"According to the text, a global organization is one that contracts with another company abroad to perform an activity it used to do itself.","options":["True","False"],"answer":1,"why":"غلط. هذا تعريف outsourcing. الـ global organization = منظمة تعمل وتتنافس في أكثر من دولة (operate and compete in more than one country) زي Samsung و Airbus.","wrong":[{"i":0,"mis":"gen.neighbor","note":"كلمة abroad خلّت الجملة تبان عالمية، بس «يتعاقد مع شركة ثانية تسوي نشاطه» هو outsourcing بالضبط."}],"tests":["global organizations","outsourcing"]},{"n":416,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"vocab","topic":"vocab-induce","stem":"In the sentence 'Too much pressure to perform may induce managers to behave unethically,' the word induce most nearly means:","options":["push or lead someone to do something","stop or prevent someone from doing something","blame or punish someone for doing something","teach or train someone to do something"],"answer":0,"why":"induce = يدفع أحد يسوي شي ما كان بيسويه. يعني الضغط الزايد يدفع المدير للتصرف غير الأخلاقي.","wrong":[{"i":1,"mis":"gen.vocab","note":"هذا عكس المعنى، الضغط هنا يدفع للغلط مو يمنعه."},{"i":2,"mis":"gen.vocab","note":"الجملة ما تتكلم عن عقاب، الضغط هو اللي يدفع المدير للتصرف الغلط."},{"i":3,"mis":"gen.vocab","note":"induce مو «يدرّب»، يمكن خلطتها بكلمة instruct أو introduce."}],"tests":["induce"]},{"n":417,"lo":"LO1-5","sec":"MGT102-CH1-S4","type":"vocab","topic":"vocab-morale","stem":"In the sentence 'Restructuring can lower the morale of the employees who keep their jobs,' the word morale most nearly means:","options":["the amount of pay and benefits","the rules of right and wrong","confidence and enthusiasm at work","the number of hours worked each week"],"answer":2,"why":"morale = معنويات الموظفين وحماسهم للشغل. بعد التقليص الباقين يخافون على وظائفهم فتنزل معنوياتهم.","wrong":[{"i":0,"mis":"gen.vocab","note":"الراتب مو المقصود، الكلام عن نفسية الباقين وخوفهم على وظائفهم."},{"i":1,"mis":"gen.vocab","note":"هذي morals (الأخلاق)، شكلها قريب من morale بس معناها مختلف تماماً."},{"i":3,"mis":"gen.vocab","note":"الساعات ممكن تزيد بعد التقليص، بس كلمة morale نفسها تعني المعنويات."}],"tests":["morale"]},{"n":418,"lo":"LO1-5","sec":"MGT102-CH1-S4","type":"vocab","topic":"vocab-autonomy","stem":"What does 'autonomy' mean?","options":["أتمتة","استقلالية","مسؤولية جماعية","رقابة"],"answer":1,"why":"autonomy = استقلالية، يعني الموظف يقرر بنفسه كيف يسوي شغله. الكتاب يقول التقنية تخلّي موظف واحد يسوي شغل كذا واحد، فيصير عنده autonomy أكثر.","wrong":[{"i":0,"mis":"gen.vocab","note":"أتمتة = automation، شكلها قريب من autonomy بس معناها آلات تشتغل بنفسها."},{"i":2,"mis":"gen.vocab","note":"المسؤولية الجماعية = collective responsibility حق الفرق ذاتية الإدارة، مو autonomy."},{"i":3,"mis":"gen.vocab","note":"الرقابة = control، وهي تقريباً عكس الاستقلالية."}],"tests":["autonomy"]},{"n":419,"lo":"LO1-6","sec":"MGT102-CH1-S4","type":"vocab","topic":"vocab-rivalry","stem":"What does 'rivalry' mean? (as in: rivalry between organizations competing around the world has increased)","options":["تعاون","منافسة","تحالف","مقارنة"],"answer":1,"why":"rivalry = منافسة بين شركات أو ناس يبون نفس الشي. الكتاب يقول المنافسة بين المنظمات داخل الدولة وبرّاها زادت بشكل كبير.","wrong":[{"i":0,"mis":"gen.vocab","note":"التعاون عكسها — rivalry يعني كل واحد يبي يسبق الثاني."},{"i":2,"mis":"gen.vocab","note":"التحالف (alliance) شراكة، بس rivalry صراع على نفس الزبون."},{"i":3,"mis":"gen.vocab","note":"المقارنة تصير بين المتنافسين، بس الكلمة نفسها معناها المنافسة."}],"tests":["rivalry"]},{"n":901,"lo":"LO1-1","sec":"CASE","type":"case","topic":"fig11-efficiency-effectiveness","stem":"Look at the company before Hind's changes. According to Figure 1.1 in the book, which description fits Wadi Al-Aqiq Dates?","img":"img/mgt102/figure-1-1.png","caseId":"C1-A","options":["Low efficiency and high effectiveness","High efficiency and high effectiveness","High efficiency and low effectiveness","Low efficiency and low effectiveness"],"answer":2,"why":"المصنع يستخدم موارده زين (هدر قليل وتكلفة قليلة) يعني efficiency عالية، بس المنتج الزبون ما عاد يبيه يعني effectiveness منخفضة. هذي بالضبط خانة «A high-quality product that customers do not want» في Figure 1.1.","wrong":[{"i":0,"mis":"c1.fig11-cells","note":"قلب خانات Figure 1.1: خانة low efficiency/high effectiveness هي المنتج اللي الزبون يبيه بس غالي، وهنا العكس، الإنتاج رخيص والزبون ما عاد يبيه."},{"i":1,"mis":"c1.one-e-only","note":"شاف إنتاج المصنع عالي وجودته عالية وحسب الأداء عالي، بس الأداء العالي يحتاج الاثنين، والمبيعات طايحة لأن الهدف (علب الهدايا) ما عاد مناسب."},{"i":3,"mis":"c1.eff-vs-effect","note":"حسب نزول المبيعات معناه كفاءة منخفضة، بس الكفاءة عن استخدام الموارد، والمصنع هدره قليل وتكلفته قليلة."}],"tests":["efficiency","effectiveness","organizational performance","figure 1.1"]},{"n":902,"lo":"LO1-2","sec":"CASE","type":"case","topic":"planning-three-steps","stem":"Hind set the 30 percent target, chose where to sell the snack packs, and decided how much budget each product line would get. Together, these three decisions are part of which managerial function?","caseId":"C1-A","options":["Planning","Organizing","Leading","Controlling"],"answer":0,"why":"حطت هدف، واختارت استراتيجية توصلها له، وقررت كيف توزّع الميزانية — هذي خطوات planning الثلاث بالترتيب. الفخ: توزيع الموارد هنا جزء من التخطيط، مو organizing.","wrong":[{"i":1,"mis":"c1.plan-vs-organize","note":"شاف توزيع الميزانية وقال تنظيم، بس الكتاب يحط allocate resources كخطوة ثالثة من planning، والتنظيم في القصة هو دمج الأقسام وتغيير مين يرفع لمين."},{"i":2,"mis":"gen.neighbor","note":"القيادة يعني رؤية وتحفيز وتنشيط الموظفين، وما في القرارات الثلاث أي تحفيز أو توجيه للناس."},{"i":3,"mis":"c1.plan-vs-control","note":"الرقابة هي المقارنة الشهرية للمبيعات بالهدف، وهنا هي تحط الهدف نفسه وتختار الطريق له."}],"tests":["planning","three steps of planning","organizing","controlling"]},{"n":903,"lo":"LO1-3","sec":"CASE","type":"case","topic":"middle-manager","stem":"Which term from the book best describes Salem's position in the company?","caseId":"C1-A","options":["First-line manager","Middle manager","Top manager","Chief operating officer (COO)"],"answer":1,"why":"Salem يشرف على مشرفين الورديات (first-line managers) ويرفع لنائب الرئيس (top)، ويدوّر أحسن طريقة لاستخدام الموارد — هذا تعريف middle manager بالحرف.","wrong":[{"i":0,"mis":"c1.level-duties","note":"اختاره لأنه داخل المصنع وقريب من الإنتاج، بس الـ first-line هو Faisal اللي يشرف على العمال يومياً، و Salem يشرف على المشرفين."},{"i":2,"mis":"c1.level-duties","note":"اختاره لأن Salem مسؤول عن المصنع كله ويرفع لنائب رئيس فحسبه من الكبار، بس الـ top manager مسؤول عن كل الأقسام (cross-departmental) ويحط أهداف الشركة، و Salem يشرف على مشرفين ويرفع لـ top manager."},{"i":3,"mis":"c1.ceo-coo-tmt","note":"غرّته كلمة operations، بس الـ COO مدير أعلى يتجهّز ليصير CEO، و Salem مدير مصنع يرفع لنائب رئيس."}],"tests":["middle manager","first-line manager","top manager","chief operating officer (coo)","levels of management"]},{"n":904,"lo":"LO1-4","sec":"CASE","type":"case","topic":"conceptual-skills","stem":"Reem looked past the drivers' explanation and found the real reason behind the late deliveries. Which term from the book best describes the ability she showed here?","caseId":"C1-B","options":["Technical skills","Conceptual skills","Human skills","Core competency"],"answer":1,"why":"Reem ما صدّقت السبب الظاهر (الزحمة)، حلّلت العملية كلها وفرّقت بين النتيجة (التأخير) والسبب الحقيقي (التحميل الغلط). هذا تعريف conceptual skills: analyze and diagnose a situation و distinguish between cause and effect.","wrong":[{"i":0,"mis":"c1.skills-swap","note":"حسبها معرفة فنية بشغل التوصيل، بس اللي سوّته تحليل وتشخيص للموقف وتفريق بين السبب والنتيجة، مو مهارة خاصة بوظيفة معيّنة."},{"i":2,"mis":"c1.skills-swap","note":"المهارات الإنسانية عن فهم سلوك الناس وتغييره وقيادتهم، و Reem ما غيّرت سلوك السواقين، هي شخّصت المشكلة."},{"i":3,"mis":"c1.dept-core","note":"الـ core competency مهارات ومعرفة قسم كامل تخلّي الشركة تتفوّق على منافسينها، مو مهارة شخصية عند مدير وحده."}],"tests":["conceptual skills","human skills","technical skills","core competency"]},{"n":905,"lo":"LO1-5","sec":"CASE","type":"case","topic":"outsourcing-vs-restructuring","stem":"Moving the customer call centre to a company in the Philippines is an example of which change in management practice?","caseId":"C1-B","options":["Restructuring","Using remote workers","Empowerment","Outsourcing"],"answer":3,"why":"تعاقدت مع شركة ثانية برّا البلد عشان تسوي شغل كانت الشركة تسويه بنفسها — هذا تعريف outsourcing بالحرف. وما أحد خسر وظيفته، فمو restructuring.","wrong":[{"i":0,"mis":"c1.restruct-vs-outsource","note":"اختاره لأن الهدف تقليل التكاليف، بس restructuring يعني تقليص بإلغاء وظائف أعداد كبيرة، وهنا ما أحد خسر وظيفته والشغل راح لشركة ثانية."},{"i":1,"mis":"gen.neighbor","note":"شاف الموظفين بعيدين في بلد ثاني، بس remote workers هم موظفين الشركة نفسها يشتغلون من البيت أو برّا المكتب بانتظام، وموظفين الكول سنتر هنا تبع شركة ثانية."},{"i":2,"mis":"c1.empower-teams","note":"التمكين يعني توسيع معرفة الموظف ومهامه وصلاحية قراره، وما صار شي من هذا، الشركة بس نقلت نشاط لشركة ثانية."}],"tests":["outsourcing","restructuring","remote workers","empowerment"]},{"n":906,"lo":"LO1-6","sec":"CASE","type":"case","topic":"global-crisis-management","stem":"Reem's reaction to the earthquake is an example of which practice from the book, and how does the book classify the cause of this crisis?","caseId":"C1-B","options":["Global crisis management; natural cause","Global crisis management; human cause","Turnaround management; natural cause","Turnaround management; human cause"],"answer":0,"why":"كوّنت فريق للقرار السريع والتواصل، وحددت مين يقود ومين يرفع لمين — هذي من اختيارات crisis management الأربعة. والزلازل الكتاب يحطها صراحة تحت natural causes.","wrong":[{"i":1,"mis":"c1.crisis-causes","note":"حسب أي أزمة توقف الشغل من صنع الإنسان، بس الكتاب يحط earthquakes صراحة تحت natural causes مع الأعاصير والحرائق."},{"i":2,"mis":"c1.turnaround-mix","note":"turnaround management لشركة متعثّرة تواجه الإفلاس وتحتاج رؤية جديدة، والشركة هنا رابحة وبس تتعامل مع أزمة مفاجئة."},{"i":3,"mis":"c1.turnaround-mix","note":"غلط في الجزئين: الشركة مو متعثّرة عشان تكون turnaround، والزلزال سبب طبيعي مو بشري."}],"tests":["crisis management","natural causes","human causes","turnaround management","global crisis management"]}]};
